"""Writes the complete TenderBot AI repository to ./tenderbot-ai/ and zips it as tenderbot-ai-production.zip.

Usage:  python build_zip.py
"""
import shutil
import zipfile
from pathlib import Path

PROJECT_DIR = "tenderbot-ai"
ZIP_NAME = "tenderbot-ai-production.zip"

FILES = {
    'README.md': '# TenderBot AI — Agentic Tender Hunter, Bid Predictor & Tax Assistant\n\nमराठी भाषेतील AI "डिजिटल मॅनेजर" for Maharashtra contractors: tender discovery, eligibility gap analysis,\nL1 bid-rate prediction, EMD/BG kits, vendor marketplace, document vault, payment-delay notices, GST advice,\nand WhatsApp + Marathi voice approval before any submission.\n\nStack: Python 3.11+, FastAPI, Pydantic v2, SQLAlchemy 2, LangChain + OpenAI GPT-4o, Twilio (WhatsApp + Voice).\n\n## Quick start\n```bash\npython -m venv .venv && source .venv/bin/activate\npip install -r requirements.txt\ncp .env.example .env        # fill in keys\nuvicorn main:app --reload\n```\nOpen http://localhost:8000/docs. Twilio webhooks need a public URL (e.g. ngrok) set as `PUBLIC_BASE_URL`:\n- WhatsApp inbound webhook → `POST {PUBLIC_BASE_URL}/whatsapp-webhook`\n- Voice calls are initiated by the API; Twilio fetches `/voice-prompt/{id}` and `/voice-response/{id}`.\n\nWithout `OPENAI_API_KEY` / Twilio credentials the app still runs: messages return as **dry runs** (not sent),\nand features that need GPT-4o (extracting requirements from raw `tender_text`) return a clear error.\n\nRegenerate the whole repo as a zip: `python build_zip.py` → `tenderbot-ai-production.zip`.\n\n## मोबाइल ॲप (PWA)\nOpen `{PUBLIC_BASE_URL}/app` in Chrome on your phone → menu ⋮ → **Add to Home screen / Install app**.\nScreens: टेंडर शोध · बिड रेट · सबमिशन मंजुरी · डॉक्युमेंट व्हॉल्ट · GST सल्ला · प्रोफाइल.\nAPK: paste the `/app` URL into pwabuilder.com and download the Android package.\nLogin is currently just the phone number (no OTP) — add OTP login before onboarding real customers.\n\n## Business rules (enforced in `database.check_access`)\n| Status | Access |\n|---|---|\n| Trial (day 1–15) | everything |\n| Basic ₹999 | analysis, alerts, document vault, draft + exportable GST billing |\n| VIP ₹5,000 | all 6 features |\n| Day 16+, no plan | locked: submission, competitor AI, voice calls, GST export, all VIP features, alerts. Returns HTTP 402 with the Marathi paywall message. Analysis and draft GST preview stay open. |\n\n## Data-sourcing rules (no hallucination)\n- **Competitor AI** uses only public awarded-tender results (Mahatenders / CPPP) stored in `awarded_tenders`.\n  Fewer than `MIN_HISTORY_SAMPLES` matches → response is exactly "जुना डेटा उपलब्ध नाही".\n  Percentages are relative to the estimated cost (SSR-based); negative = below.\n- **Marketplace** returns contacts/rates only from the Internal Verified Vendor Database (`verified_vendors`).\n- Submission is reported as `SUBMITTED` only if your `SUBMISSION_WEBHOOK_URL` service confirms with 2xx.\n  Portal submission needs your DSC, so by default an approved bid is `APPROVED_AWAITING_PORTAL_SUBMISSION`.\n\n## Endpoints\n| Method | Path | Purpose |\n|---|---|---|\n| GET | `/` | health check |\n| POST | `/analyze-tender` | document gap analysis + WhatsApp alert |\n| POST | `/predict-bid-rate` | competitor AI → L1 %, bid amount, profit margin |\n| POST | `/request-submit-approval` | WhatsApp prompt + Marathi voice call |\n| POST | `/whatsapp-webhook` | YES/NO (also हो/नाही) → execute or cancel |\n| POST | `/generate-payment-notice` | formal Marathi follow-up letter |\n| POST | `/get-tax-advice` | GST liability, ITC, CA-ready breakdown |\n| POST | `/generate-emd-kit` | EMD / BG document kit |\n| GET | `/marketplace/search` | verified vendors |\n| POST/GET | `/vault/documents` | document vault |\n| POST | `/discover-tenders` | read a public listing page (allow-listed hosts) and save tenders |\n| GET/POST | `/tenders/search`, `/tenders` | search / add tenders |\n| GET/POST | `/me` | profile + plan status |\n| GET | `/submissions?phone=` | list submissions |\n| POST | `/submissions/{id}/decision` | approve/cancel inside the app |\n| GET | `/app` | the PWA |\n| POST | `/admin/*` (header `X-Admin-Key`) | ingest awarded data, add vendors, set plan, run vault alerts |\n\nFeed the competitor AI first: `POST /admin/ingest-awarded-data` with `{"source":"Mahatenders","url":"..."}`\nor `{"source":"CPPP","records":[{...}]}`. The scraper reads only public HTML tables; it does not bypass captchas/logins.\n\n## Example\n```bash\ncurl -X POST localhost:8000/get-tax-advice -H \'content-type: application/json\' -d \'{\n  "phone":"+919876543210","taxable_value":1000000,\n  "purchases":[{"description":"Cement","taxable_value":400000,"gst_rate_percent":18,"itc_eligible":true}]}\'\n```\n\nGST figures are computed from your inputs; confirm with your CA before filing.\n',
    'requirements.txt': 'fastapi>=0.115,<1.0\nuvicorn[standard]>=0.30\npydantic>=2.7,<3.0\npydantic-settings>=2.3\nsqlalchemy>=2.0,<3.0\nlangchain-openai>=0.2\nlangchain-core>=0.3\ntwilio>=9.0\nhttpx>=0.27\nbeautifulsoup4>=4.12\npython-multipart>=0.0.9\npython-dotenv>=1.0\npsycopg2-binary>=2.9\n',
    '.env.example': '# --- App ---\nDATABASE_URL=sqlite:///./tenderbot.db\n# PostgreSQL example: postgresql+psycopg2://user:password@localhost:5432/tenderbot\nPUBLIC_BASE_URL=https://your-public-domain.example.com\nADMIN_API_KEY=change-this-long-random-secret\n\n# --- OpenAI ---\nOPENAI_API_KEY=\nOPENAI_MODEL=gpt-4o\n\n# --- Twilio ---\nTWILIO_ACCOUNT_SID=\nTWILIO_AUTH_TOKEN=\nTWILIO_WHATSAPP_FROM=whatsapp:+14155238886\nTWILIO_VOICE_FROM=+1XXXXXXXXXX\n# Optional: approved Content Template SID with YES/NO quick-reply buttons ({{1}}=tender title, {{2}}=amount)\nTWILIO_APPROVAL_CONTENT_SID=\nVALIDATE_TWILIO_SIGNATURE=true\n\n# --- Business rules ---\nTRIAL_DAYS=15\nMIN_HISTORY_SAMPLES=3\nEXPIRY_ALERT_DAYS=30\nGST_RATE_PERCENT=18\nENABLE_SCHEDULER=true\nVAULT_CHECK_INTERVAL_HOURS=24\n\n# --- Optional integrations ---\n# If set, an approved submission is POSTed here as JSON (your own DSC/portal submission service)\nSUBMISSION_WEBHOOK_URL=\n# Public portals the scraper is allowed to read (comma separated host suffixes)\nALLOWED_SCRAPE_HOSTS=mahatenders.gov.in,eprocure.gov.in,etenders.gov.in\n',
    'config.py': '"""Central configuration loaded from environment variables / .env."""\nfrom functools import lru_cache\n\nfrom pydantic_settings import BaseSettings, SettingsConfigDict\n\n\nclass Settings(BaseSettings):\n    model_config = SettingsConfigDict(env_file=".env", env_file_encoding="utf-8", extra="ignore")\n\n    app_name: str = "TenderBot AI"\n    app_version: str = "1.0.0"\n    database_url: str = "sqlite:///./tenderbot.db"\n    public_base_url: str = "http://localhost:8000"\n    admin_api_key: str = ""\n\n    openai_api_key: str = ""\n    openai_model: str = "gpt-4o"\n\n    twilio_account_sid: str = ""\n    twilio_auth_token: str = ""\n    twilio_whatsapp_from: str = "whatsapp:+14155238886"\n    twilio_voice_from: str = ""\n    twilio_approval_content_sid: str = ""\n    validate_twilio_signature: bool = False\n\n    trial_days: int = 15\n    basic_price: int = 999\n    vip_price: int = 5000\n    min_history_samples: int = 3\n    expiry_alert_days: int = 30\n    gst_rate_percent: float = 18.0\n    gst_tds_rate_percent: float = 2.0\n    gst_tds_threshold: float = 250000.0\n    enable_scheduler: bool = True\n    vault_check_interval_hours: int = 24\n\n    submission_webhook_url: str = ""\n    allowed_scrape_hosts: str = "mahatenders.gov.in,eprocure.gov.in,etenders.gov.in"\n\n    @property\n    def twilio_configured(self) -> bool:\n        return bool(self.twilio_account_sid and self.twilio_auth_token)\n\n    @property\n    def scrape_hosts(self) -> list[str]:\n        return [h.strip().lower() for h in self.allowed_scrape_hosts.split(",") if h.strip()]\n\n\n@lru_cache\ndef get_settings() -> Settings:\n    return Settings()\n',
    'database.py': '"""SQLAlchemy models, session handling and subscription/access rules."""\nfrom __future__ import annotations\n\nimport re\nfrom datetime import date, datetime, timezone\nfrom typing import Iterator\n\nfrom sqlalchemy import (\n    JSON,\n    Date,\n    DateTime,\n    Float,\n    ForeignKey,\n    Integer,\n    String,\n    Text,\n    UniqueConstraint,\n    create_engine,\n    select,\n)\nfrom sqlalchemy.orm import DeclarativeBase, Mapped, Session, mapped_column, relationship, sessionmaker\n\nfrom config import get_settings\nfrom system_prompt import PAYWALL_MESSAGE_MR, UPGRADE_VIP_MESSAGE_MR\n\nsettings = get_settings()\n\nengine = create_engine(\n    settings.database_url,\n    pool_pre_ping=True,\n    connect_args={"check_same_thread": False} if settings.database_url.startswith("sqlite") else {},\n)\nSessionLocal = sessionmaker(bind=engine, autoflush=False, expire_on_commit=False)\n\n\ndef utcnow() -> datetime:\n    return datetime.now(timezone.utc).replace(tzinfo=None)\n\n\ndef normalize_phone(raw: str) -> str:\n    """Return E.164 phone (+91 assumed for 10-digit numbers). Raises ValueError if invalid."""\n    cleaned = (raw or "").replace("whatsapp:", "").strip()\n    digits = re.sub(r"\\D", "", cleaned)\n    if cleaned.startswith("+"):\n        result = "+" + digits\n    elif len(digits) == 10:\n        result = "+91" + digits\n    elif len(digits) == 12 and digits.startswith("91"):\n        result = "+" + digits\n    else:\n        result = "+" + digits\n    if not 9 <= len(result) - 1 <= 15:\n        raise ValueError("अवैध फोन नंबर")\n    return result\n\n\nclass Base(DeclarativeBase):\n    pass\n\n\nclass Contractor(Base):\n    __tablename__ = "contractors"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    phone: Mapped[str] = mapped_column(String(20), unique=True, index=True)\n    name: Mapped[str | None] = mapped_column(String(200), nullable=True)\n    contractor_class: Mapped[str | None] = mapped_column(String(50), nullable=True)\n    categories: Mapped[list] = mapped_column(JSON, default=list)\n    districts: Mapped[list] = mapped_column(JSON, default=list)\n    annual_turnover: Mapped[float | None] = mapped_column(Float, nullable=True)\n    plan: Mapped[str] = mapped_column(String(10), default="none")  # none | basic | vip\n    plan_expires_at: Mapped[datetime | None] = mapped_column(DateTime, nullable=True)\n    trial_started_at: Mapped[datetime] = mapped_column(DateTime, default=utcnow)\n    created_at: Mapped[datetime] = mapped_column(DateTime, default=utcnow)\n\n    documents: Mapped[list["VaultDocument"]] = relationship(back_populates="contractor", cascade="all, delete-orphan")\n\n    def trial_day(self, now: datetime | None = None) -> int:\n        now = now or utcnow()\n        return (now.date() - self.trial_started_at.date()).days + 1\n\n    def effective_plan(self, now: datetime | None = None) -> str:\n        """trial | basic | vip | expired"""\n        now = now or utcnow()\n        if self.plan in ("basic", "vip") and (self.plan_expires_at is None or self.plan_expires_at > now):\n            return self.plan\n        if self.trial_day(now) <= get_settings().trial_days:\n            return "trial"\n        return "expired"\n\n\nclass Tender(Base):\n    __tablename__ = "tenders"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    tender_ref: Mapped[str] = mapped_column(String(120), unique=True, index=True)\n    title: Mapped[str] = mapped_column(Text)\n    department: Mapped[str] = mapped_column(String(300))\n    category: Mapped[str] = mapped_column(String(100))\n    district: Mapped[str | None] = mapped_column(String(100), nullable=True)\n    estimated_cost: Mapped[float] = mapped_column(Float)\n    emd_amount: Mapped[float | None] = mapped_column(Float, nullable=True)\n    source_url: Mapped[str | None] = mapped_column(String(500), nullable=True)\n    created_at: Mapped[datetime] = mapped_column(DateTime, default=utcnow)\n\n\nclass AwardedTender(Base):\n    """Public, already-awarded tender results (Mahatenders / CPPP). Only source for competitor AI."""\n\n    __tablename__ = "awarded_tenders"\n    __table_args__ = (UniqueConstraint("tender_ref", "source", name="uq_awarded_ref_source"),)\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    tender_ref: Mapped[str] = mapped_column(String(120), index=True)\n    title: Mapped[str | None] = mapped_column(Text, nullable=True)\n    department: Mapped[str | None] = mapped_column(String(300), nullable=True, index=True)\n    category: Mapped[str | None] = mapped_column(String(100), nullable=True, index=True)\n    district: Mapped[str | None] = mapped_column(String(100), nullable=True)\n    estimated_cost: Mapped[float] = mapped_column(Float)\n    awarded_amount: Mapped[float] = mapped_column(Float)\n    percent_vs_estimate: Mapped[float] = mapped_column(Float)  # negative = below estimate/SSR\n    winner_name: Mapped[str | None] = mapped_column(String(300), nullable=True)\n    award_date: Mapped[date | None] = mapped_column(Date, nullable=True)\n    source: Mapped[str] = mapped_column(String(50), default="Mahatenders")  # Mahatenders | CPPP\n    source_url: Mapped[str | None] = mapped_column(String(500), nullable=True)\n\n\nclass VerifiedVendor(Base):\n    """Internal Verified Vendor Database. Only source for marketplace contacts and rates."""\n\n    __tablename__ = "verified_vendors"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    name: Mapped[str] = mapped_column(String(200))\n    category: Mapped[str] = mapped_column(String(100), index=True)  # JCB, crane, cement, steel, labour ...\n    district: Mapped[str] = mapped_column(String(100), index=True)\n    phone: Mapped[str] = mapped_column(String(20))\n    rate: Mapped[float | None] = mapped_column(Float, nullable=True)\n    rate_unit: Mapped[str | None] = mapped_column(String(50), nullable=True)\n    last_verified_on: Mapped[date] = mapped_column(Date)\n    verified_by: Mapped[str | None] = mapped_column(String(100), nullable=True)\n\n\nclass VaultDocument(Base):\n    __tablename__ = "vault_documents"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    contractor_id: Mapped[int] = mapped_column(ForeignKey("contractors.id"), index=True)\n    doc_type: Mapped[str] = mapped_column(String(150))\n    doc_number: Mapped[str | None] = mapped_column(String(100), nullable=True)\n    expiry_date: Mapped[date | None] = mapped_column(Date, nullable=True)\n    file_ref: Mapped[str | None] = mapped_column(String(500), nullable=True)\n    last_alert_on: Mapped[date | None] = mapped_column(Date, nullable=True)\n    created_at: Mapped[datetime] = mapped_column(DateTime, default=utcnow)\n\n    contractor: Mapped[Contractor] = relationship(back_populates="documents")\n\n\nclass PaymentBill(Base):\n    __tablename__ = "payment_bills"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    contractor_id: Mapped[int] = mapped_column(ForeignKey("contractors.id"), index=True)\n    department: Mapped[str] = mapped_column(String(300))\n    work_name: Mapped[str] = mapped_column(Text)\n    work_order_no: Mapped[str | None] = mapped_column(String(100), nullable=True)\n    bill_no: Mapped[str] = mapped_column(String(100))\n    bill_amount: Mapped[float] = mapped_column(Float)\n    bill_submitted_on: Mapped[date] = mapped_column(Date)\n    desk_trail: Mapped[list] = mapped_column(JSON, default=list)\n    last_notice_on: Mapped[date | None] = mapped_column(Date, nullable=True)\n    notices_sent: Mapped[int] = mapped_column(Integer, default=0)\n\n\nclass Submission(Base):\n    __tablename__ = "submissions"\n\n    id: Mapped[int] = mapped_column(primary_key=True)\n    contractor_id: Mapped[int] = mapped_column(ForeignKey("contractors.id"), index=True)\n    tender_ref: Mapped[str] = mapped_column(String(120))\n    tender_title: Mapped[str] = mapped_column(Text)\n    bid_amount: Mapped[float] = mapped_column(Float)\n    # PENDING | CANCELLED | APPROVED_AWAITING_PORTAL_SUBMISSION | SUBMITTED | APPROVED_SUBMISSION_FAILED\n    status: Mapped[str] = mapped_column(String(50), default="PENDING", index=True)\n    decision_channel: Mapped[str | None] = mapped_column(String(20), nullable=True)\n    status_detail: Mapped[str | None] = mapped_column(Text, nullable=True)\n    whatsapp_sid: Mapped[str | None] = mapped_column(String(64), nullable=True)\n    call_sid: Mapped[str | None] = mapped_column(String(64), nullable=True)\n    created_at: Mapped[datetime] = mapped_column(DateTime, default=utcnow)\n    decided_at: Mapped[datetime | None] = mapped_column(DateTime, nullable=True)\n\n\n# ---------------------------------------------------------------- access rules\nALWAYS_OPEN_FEATURES = {"analyze", "tax_draft"}\nBASIC_FEATURES = ALWAYS_OPEN_FEATURES | {"alerts", "vault", "tax_export"}\n# VIP-only (also locked after trial without a plan): predict_bid, submit, voice, bg_emd,\n# marketplace, payment_notice\n\n\ndef check_access(contractor: Contractor, feature: str) -> tuple[bool, str]:\n    """Return (allowed, Marathi message when blocked)."""\n    plan = contractor.effective_plan()\n    if plan in ("trial", "vip"):\n        return True, ""\n    if plan == "basic":\n        return (True, "") if feature in BASIC_FEATURES else (False, UPGRADE_VIP_MESSAGE_MR)\n    # expired trial, no active paid plan\n    return (True, "") if feature in ALWAYS_OPEN_FEATURES else (False, PAYWALL_MESSAGE_MR)\n\n\n# ---------------------------------------------------------------- helpers\ndef init_db() -> None:\n    Base.metadata.create_all(bind=engine)\n\n\ndef get_db() -> Iterator[Session]:\n    db = SessionLocal()\n    try:\n        yield db\n    finally:\n        db.close()\n\n\ndef get_or_create_contractor(db: Session, phone: str, **profile) -> Contractor:\n    """Fetch contractor by phone (creating it, and starting the free trial, on first contact)."""\n    phone = normalize_phone(phone)\n    contractor = db.scalar(select(Contractor).where(Contractor.phone == phone))\n    if contractor is None:\n        contractor = Contractor(phone=phone, categories=[], districts=[])\n        db.add(contractor)\n    for key, value in profile.items():\n        if value not in (None, [], ""):\n            setattr(contractor, key, value)\n    db.commit()\n    db.refresh(contractor)\n    return contractor\n',
    'system_prompt.py': '"""TenderBot AI master system prompt and fixed Marathi user-facing messages."""\n\nOLD_DATA_MSG_MR = "जुना डेटा उपलब्ध नाही"\nNO_VENDOR_MSG_MR = "Internal Verified Vendor Database मध्ये ही माहिती सध्या उपलब्ध नाही."\n\nPAYWALL_MESSAGE_MR = (\n    "भाऊ, तुमची १५ दिवसांची मोफत ट्रायल संपली आहे. पुढे टेंडर सबमिशन, व्हॉट्सॲप/कॉल अलर्ट आणि "\n    "सीए-रेडी जीएसटी बिलिंग चालू ठेवण्यासाठी तुमचा ₹९९९ किंवा ₹५,००० चा प्लॅन सुरू करा."\n)\n\nUPGRADE_VIP_MESSAGE_MR = (\n    "भाऊ, हे फीचर VIP Premium (₹५,०००/महिना) प्लॅनमध्ये मिळते. Basic (₹९९९/महिना) मध्ये "\n    "स्टँडर्ड अलर्ट्स, डॉक्युमेंट व्हॉल्ट आणि ड्राफ्ट जीएसटी बिलिंग मिळते. VIP प्लॅनवर अपग्रेड करा."\n)\n\nMASTER_SYSTEM_PROMPT = """तू TenderBot AI आहेस — महाराष्ट्र आणि भारतातील सिव्हिल, इन्फ्रास्ट्रक्चर, लेबर/सिक्युरिटी एजन्सी,\nवाळू/खनिज लिलाव आणि मटेरियल सप्लाय कंत्राटदारांचा "कंत्राटदाराचा हक्काचा आणि विश्वासू डिजिटल मॅनेजर".\n\nभाषा आणि टोन:\n- स्पष्ट, व्यावहारिक, सोप्या मराठीत (बांधकाम/व्यवसायातील स्थानिक शब्द वापर: SSR, EMD, BG, L1, रनिंग बिल, फायनल बिल).\n- आदरपूर्वक, थेट आणि मदतीचा टोन. उत्तर लहान आणि कृती-केंद्रित ठेव.\n\nकठोर नियम (उल्लंघन करू नकोस):\n1. NO HALLUCINATION: कोणतेही आकडे, दर, टक्केवारी, नावे, फोन नंबर, तारखा स्वतः बनवू नकोस.\n   फक्त दिलेल्या संदर्भ-डेटामधूनच बोल. डेटा नसेल तर स्पष्ट सांग.\n2. स्पर्धक विश्लेषण (Competitor AI): फक्त Mahatenders / CPPP वरील सार्वजनिक, आधीच अवार्ड झालेल्या टेंडर्सच्या डेटामधून.\n   पुरेसा जुना डेटा नसेल तर नेमके "जुना डेटा उपलब्ध नाही" असे सांग; अंदाज लावू नकोस.\n3. मार्केटप्लेस (JCB/क्रेन/सिमेंट/स्टील/लेबर): संपर्क आणि दर फक्त Internal Verified Vendor Database मधूनच.\n   तिथे नसेल तर तसे सांग. इंटरनेटवरून किंवा आठवणीतून नंबर/दर देऊ नकोस.\n4. सबमिशन: कंत्राटदाराने स्पष्टपणे YES/होय म्हटल्याशिवाय कोणतेही टेंडर सबमिट करू नकोस.\n   पोर्टलवर प्रत्यक्ष सबमिशन झाले आहे असे फक्त स्टेटस SUBMITTED असेल तरच सांग.\n5. GST/टॅक्स: आकडेमोड दिलेल्या इनपुटवरच; अंतिम निर्णयासाठी सीए चा सल्ला घे असे नमूद कर.\n6. प्लॅन: १५ दिवस मोफत ट्रायल; Basic ₹९९९/महिना; VIP Premium ₹५,०००/महिना (सर्व ६ फीचर्स).\n"""\n\n\ndef build_task_prompt(task: str, context: str) -> str:\n    """Compose the master prompt with a task description and the verified context data."""\n    return (\n        f"{MASTER_SYSTEM_PROMPT}\\n\\nआजचे काम: {task}\\n\\n"\n        f"संदर्भ-डेटा (फक्त हाच वापर):\\n{context}\\n"\n    )\n',
    'pwa.py': '"""Marathi PWA front-end served by FastAPI: /app, /manifest.webmanifest, /sw.js, /icon-192.png, /icon-512.png."""\nfrom __future__ import annotations\n\nimport json\nimport struct\nimport zlib\nfrom functools import lru_cache\n\nfrom fastapi import APIRouter, HTTPException, Response\nfrom fastapi.responses import HTMLResponse\n\nrouter = APIRouter()\n\nMANIFEST = {\n    "name": "TenderBot AI — कंत्राटदाराचा डिजिटल मॅनेजर",\n    "short_name": "TenderBot",\n    "description": "टेंडर शोध, बिड रेट, सबमिशन मंजुरी, कागदपत्र व्हॉल्ट आणि GST सल्ला",\n    "lang": "mr",\n    "start_url": "/app",\n    "scope": "/",\n    "display": "standalone",\n    "orientation": "portrait",\n    "background_color": "#0d3b66",\n    "theme_color": "#0d3b66",\n    "icons": [\n        {"src": "/icon-192.png", "sizes": "192x192", "type": "image/png", "purpose": "any maskable"},\n        {"src": "/icon-512.png", "sizes": "512x512", "type": "image/png", "purpose": "any maskable"},\n    ],\n}\n\nSW_JS = """const CACHE=\'tenderbot-shell-v1\';\nself.addEventListener(\'install\',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll([\'/app\'])));self.skipWaiting();});\nself.addEventListener(\'activate\',e=>{e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k!==CACHE).map(k=>caches.delete(k)))));self.clients.claim();});\nself.addEventListener(\'fetch\',e=>{\n  const u=new URL(e.request.url);\n  if(e.request.method!==\'GET\'||u.pathname!==\'/app\')return;\n  e.respondWith(fetch(e.request).then(r=>{const c=r.clone();caches.open(CACHE).then(x=>x.put(\'/app\',c));return r;}).catch(()=>caches.match(\'/app\')));\n});\n"""\n\n\n@lru_cache(maxsize=4)\ndef _icon(size: int) -> bytes:\n    bg, fg, accent = (13, 59, 102), (255, 255, 255), (244, 162, 89)\n    raw = bytearray()\n    for y in range(size):\n        raw.append(0)\n        v = y / size\n        for x in range(size):\n            u = x / size\n            if 0.26 <= u <= 0.74 and 0.28 <= v <= 0.40:\n                color = fg\n            elif 0.44 <= u <= 0.56 and 0.40 < v <= 0.72:\n                color = fg\n            elif 0.30 <= u <= 0.70 and 0.76 <= v <= 0.80:\n                color = accent\n            else:\n                color = bg\n            raw += bytes(color)\n\n    def chunk(tag: bytes, data: bytes) -> bytes:\n        body = tag + data\n        return struct.pack(">I", len(data)) + body + struct.pack(">I", zlib.crc32(body) & 0xFFFFFFFF)\n\n    return (b"\\x89PNG\\r\\n\\x1a\\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", size, size, 8, 2, 0, 0, 0))\n            + chunk(b"IDAT", zlib.compress(bytes(raw), 9)) + chunk(b"IEND", b""))\n\n\n@router.get("/manifest.webmanifest", include_in_schema=False)\ndef manifest() -> Response:\n    return Response(json.dumps(MANIFEST, ensure_ascii=False), media_type="application/manifest+json")\n\n\n@router.get("/sw.js", include_in_schema=False)\ndef service_worker() -> Response:\n    return Response(SW_JS, media_type="application/javascript", headers={"Cache-Control": "no-cache"})\n\n\n@router.get("/icon-{size}.png", include_in_schema=False)\ndef icon(size: int) -> Response:\n    if size not in (192, 512):\n        raise HTTPException(404)\n    return Response(_icon(size), media_type="image/png", headers={"Cache-Control": "public, max-age=604800"})\n\n\n@router.get("/app", response_class=HTMLResponse, include_in_schema=False)\ndef app_page() -> HTMLResponse:\n    return HTMLResponse(APP_HTML, headers={"Cache-Control": "no-cache"})\n\n\nAPP_HTML = r"""<!DOCTYPE html>\n<html lang="mr"><head><meta charset="utf-8">\n<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">\n<meta name="theme-color" content="#0d3b66">\n<link rel="manifest" href="/manifest.webmanifest">\n<link rel="icon" href="/icon-192.png"><link rel="apple-touch-icon" href="/icon-192.png">\n<title>TenderBot AI</title>\n<style>\n:root{--p:#0d3b66;--a:#f4a259;--bg:#f2f5fa;--c:#fff;--t:#1b2430;--m:#64748b;--ok:#15803d;--bad:#b91c1c;--warn:#b45309;--line:#e2e8f0}\n*{box-sizing:border-box}\nbody{margin:0;font-family:system-ui,"Noto Sans Devanagari",Roboto,sans-serif;background:var(--bg);color:var(--t);padding-top:env(safe-area-inset-top);padding-bottom:calc(68px + env(safe-area-inset-bottom));font-size:16px}\nheader{position:sticky;top:0;z-index:5;background:var(--p);color:#fff;display:flex;align-items:center;justify-content:space-between;padding:10px 14px}\nheader b{font-size:18px}.badge{background:var(--a);color:#1b2430;border-radius:99px;padding:3px 10px;font-size:12px;font-weight:700;margin-left:8px}\nheader button{background:none;border:0;color:#fff;font-size:22px}\nmain{padding:12px;max-width:640px;margin:auto}\n.screen{display:none}.screen.on{display:block}\n.card{background:var(--c);border-radius:14px;padding:14px;margin-bottom:12px;box-shadow:0 1px 3px rgba(0,0,0,.08)}\nh2{margin:0 0 8px;font-size:18px}h3{margin:12px 0 6px;font-size:15px}\nlabel{display:block;font-size:13px;color:var(--m);margin:10px 0 4px}\ninput,select,textarea{width:100%;padding:11px;border:1px solid #cbd5e1;border-radius:10px;font-size:16px;background:#fff;font-family:inherit}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.btn{width:100%;margin-top:14px;padding:13px;border:0;border-radius:10px;background:var(--p);color:#fff;font-size:16px;font-weight:700}\n.btn.sec{background:#e8eef7;color:var(--p)}.btn.ok{background:var(--ok)}.btn.bad{background:var(--bad)}.btn.sm{width:auto;margin:6px 6px 0 0;padding:8px 12px;font-size:14px}\n.btn:disabled{opacity:.6}\nnav{position:fixed;bottom:0;left:0;right:0;display:flex;background:#fff;border-top:1px solid var(--line);padding-bottom:env(safe-area-inset-bottom);z-index:6}\nnav button{flex:1;border:0;background:none;padding:8px 2px;font-size:11px;color:var(--m)}\nnav button span{display:block;font-size:22px}nav button.on{color:var(--p);font-weight:700}\n.chip{display:inline-block;padding:2px 9px;border-radius:99px;font-size:12px;font-weight:700;background:#e2e8f0}\n.chip.ok{background:#dcfce7;color:var(--ok)}.chip.bad{background:#fee2e2;color:var(--bad)}.chip.warn{background:#fef3c7;color:var(--warn)}\n.muted{color:var(--m);font-size:13px}.err{background:#fee2e2;color:#7f1d1d;border-radius:10px;padding:12px;margin-top:10px}\n.pay{background:#fff7ed;color:#9a3412;border:1px solid #fdba74;border-radius:10px;padding:12px;margin-top:10px;font-weight:600}\n.info{background:#eff6ff;color:#1e3a8a;border-radius:10px;padding:10px;margin-top:10px;font-size:14px}\ntable{width:100%;border-collapse:collapse;font-size:14px}td{padding:6px 4px;border-bottom:1px solid var(--line)}td:last-child{text-align:right;white-space:nowrap}\n.kpi{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:8px 0}.kpi div{background:#f1f5f9;border-radius:10px;padding:10px}.kpi small{color:var(--m);display:block}.kpi b{font-size:17px}\nsummary{font-weight:700;cursor:pointer}details>summary{margin-bottom:6px}\n.row{display:flex;gap:8px;align-items:center}.row input[type=checkbox]{width:auto}\ndialog{border:0;border-radius:16px;padding:16px;width:min(94vw,560px);max-height:88vh;overflow:auto}\ndialog::backdrop{background:rgba(0,0,0,.5)}\n#toast{position:fixed;left:12px;right:12px;bottom:84px;background:#1b2430;color:#fff;padding:12px;border-radius:10px;display:none;z-index:20;text-align:center}\n.pr{border:1px dashed #cbd5e1;border-radius:10px;padding:8px;margin-top:8px}\n</style></head><body>\n<header><div><b>🏗️ TenderBot AI</b><span class="badge" id="planBadge">—</span></div><button onclick="show(\'profile\')" aria-label="प्रोफाइल">👤</button></header>\n<main>\n\n<section id="s-search" class="screen">\n <div class="card"><h2>🔍 टेंडर शोध</h2>\n  <label>कीवर्ड</label><input id="sf_q" placeholder="उदा. रस्ता, पूल, पाणीपुरवठा">\n  <div class="grid2"><div><label>श्रेणी</label><input id="sf_category" list="cats" placeholder="civil"></div><div><label>जिल्हा</label><input id="sf_district" placeholder="पुणे"></div></div>\n  <label>विभाग</label><input id="sf_department" placeholder="PWD, जिल्हा परिषद…">\n  <div class="grid2"><div><label>किमान किंमत (₹)</label><input id="sf_min_cost" type="number" inputmode="numeric"></div><div><label>कमाल किंमत (₹)</label><input id="sf_max_cost" type="number" inputmode="numeric"></div></div>\n  <button class="btn" onclick="doSearch()">शोधा</button></div>\n <div id="searchRes"></div>\n <details class="card"><summary>➕ नवीन टेंडर जोडा</summary>\n  <label>टेंडर क्रमांक</label><input id="at_id"><label>कामाचे नाव</label><input id="at_title"><label>विभाग</label><input id="at_dept">\n  <div class="grid2"><div><label>श्रेणी</label><input id="at_cat" list="cats"></div><div><label>जिल्हा</label><input id="at_dist"></div></div>\n  <div class="grid2"><div><label>अंदाजित किंमत (₹)</label><input id="at_cost" type="number" inputmode="decimal"></div><div><label>EMD (₹)</label><input id="at_emd" type="number" inputmode="decimal"></div></div>\n  <button class="btn sec" onclick="addTender()">टेंडर सेव्ह करा</button></details>\n <details class="card"><summary>🌐 पोर्टल लिंकवरून आणा</summary>\n  <p class="muted">फक्त mahatenders.gov.in / eprocure.gov.in चे सार्वजनिक यादी-पेज चालते.</p>\n  <label>पेज लिंक</label><input id="im_url" type="url"><div class="grid2"><div><label>श्रेणी</label><input id="im_cat" list="cats"></div><div><label>जिल्हा</label><input id="im_dist"></div></div>\n  <button class="btn sec" onclick="importTenders()">आणा</button><div id="imRes"></div></details>\n</section>\n\n<section id="s-predict" class="screen">\n <div class="card"><h2>📈 बिड रेट प्रेडिक्शन</h2>\n  <p class="muted">फक्त Mahatenders/CPPP च्या जुन्या अवार्ड डेटावरून. डेटा नसेल तर "जुना डेटा उपलब्ध नाही" येईल.</p>\n  <label>श्रेणी</label><input id="pr_cat" list="cats" placeholder="civil">\n  <label>विभाग</label><input id="pr_dept" placeholder="PWD">\n  <label>कामाचे नाव (ऐच्छिक)</label><input id="pr_title">\n  <div class="grid2"><div><label>अंदाजित किंमत (₹)</label><input id="pr_est" type="number" inputmode="decimal"></div><div><label>माझा खर्च अंदाज (₹)</label><input id="pr_own" type="number" inputmode="decimal"></div></div>\n  <button class="btn" onclick="runPredict()">रेट सुचवा</button></div>\n <div id="predRes"></div>\n</section>\n\n<section id="s-approval" class="screen">\n <div class="card"><h2>✅ सबमिशन अप्रूव्हल</h2>\n  <p class="muted">तुमच्या मंजुरीशिवाय काहीही सबमिट होत नाही. WhatsApp आणि मराठी कॉलवरही विचारले जाते.</p>\n  <label>टेंडर क्रमांक</label><input id="ap_id"><label>कामाचे नाव</label><input id="ap_title">\n  <label>बिड रक्कम (₹)</label><input id="ap_amt" type="number" inputmode="decimal">\n  <div class="row" style="margin-top:10px"><input type="checkbox" id="ap_call" checked><span>मराठी व्हॉइस कॉलही करा</span></div>\n  <button class="btn" onclick="reqApproval()">मंजुरी मागवा</button><div id="apRes"></div></div>\n <h3>माझी सबमिशन्स</h3><div id="subList"></div>\n</section>\n\n<section id="s-vault" class="screen">\n <div class="card"><h2>🗂️ डॉक्युमेंट व्हॉल्ट</h2><div id="vaultList"><p class="muted">लोड होत आहे…</p></div></div>\n <div class="card"><h3>कागदपत्र जोडा</h3>\n  <label>प्रकार</label><select id="vd_type">\n   <option value="GST Registration">GST नोंदणी</option><option value="PAN Card">PAN कार्ड</option><option value="PWD Registration">PWD नोंदणी</option>\n   <option value="Class-1 Certificate">Class-1 प्रमाणपत्र</option><option value="EPF Certificate">EPF</option><option value="ESIC Certificate">ESIC</option>\n   <option value="Labour Licence">कामगार परवाना</option><option value="Solvency Certificate">सॉल्व्हन्सी प्रमाणपत्र</option><option value="Turnover Certificate">उलाढाल प्रमाणपत्र</option>\n   <option value="ITR">आयकर रिटर्न (ITR)</option><option value="Udyam Registration">उद्योग आधार / Udyam</option><option value="DSC">डिजिटल सही (DSC)</option></select>\n  <label>किंवा दुसरा प्रकार लिहा</label><input id="vd_other">\n  <label>क्रमांक</label><input id="vd_num"><label>मुदत संपण्याची तारीख</label><input id="vd_exp" type="date">\n  <label>फाइल/ड्राइव्ह लिंक (ऐच्छिक)</label><input id="vd_ref" type="url">\n  <button class="btn" onclick="addDoc()">जोडा</button></div>\n</section>\n\n<section id="s-gst" class="screen">\n <div class="card"><h2>🧾 GST सल्ला</h2>\n  <label>करपात्र मूल्य (₹)</label><input id="g_val" type="number" inputmode="decimal">\n  <div class="grid2"><div><label>GST दर (%)</label><input id="g_rate" type="number" value="18" inputmode="decimal"></div>\n  <div><label>पुरवठा</label><select id="g_intra"><option value="1">राज्यांतर्गत (CGST+SGST)</option><option value="0">आंतरराज्य (IGST)</option></select></div></div>\n  <div class="row" style="margin-top:10px"><input type="checkbox" id="g_tds"><span>सरकारी विभाग GST TDS कापतो</span></div>\n  <h3>खरेदी (ITC साठी)</h3><div id="g_purch"></div>\n  <button class="btn sec" onclick="addPurchase()">+ खरेदी जोडा</button>\n  <button class="btn" onclick="runGst()">हिशोब करा</button></div>\n <div id="gstRes"></div>\n</section>\n\n<section id="s-profile" class="screen">\n <div class="card"><h2>👤 माझे प्रोफाइल</h2>\n  <label>WhatsApp नंबर (+91…)</label><input id="pf_phone" type="tel" placeholder="+919876543210">\n  <label>फर्मचे / तुमचे नाव</label><input id="pf_name">\n  <div class="grid2"><div><label>वर्ग</label><input id="pf_class" placeholder="Class 1"></div><div><label>वार्षिक उलाढाल (₹)</label><input id="pf_turn" type="number" inputmode="decimal"></div></div>\n  <label>श्रेणी (स्वल्पविरामाने)</label><input id="pf_cats" placeholder="civil, road"><label>जिल्हे (स्वल्पविरामाने)</label><input id="pf_dists" placeholder="पुणे, सातारा">\n  <button class="btn" onclick="saveProfile()">सेव्ह करा</button>\n  <button class="btn sec" id="installBtn" style="display:none" onclick="installApp()">📲 ॲप इन्स्टॉल करा</button>\n  <div id="pfRes"></div></div>\n</section>\n</main>\n\n<nav>\n <button data-s="search" onclick="show(\'search\')"><span>🔍</span>शोध</button>\n <button data-s="predict" onclick="show(\'predict\')"><span>📈</span>बिड रेट</button>\n <button data-s="approval" onclick="show(\'approval\')"><span>✅</span>मंजुरी</button>\n <button data-s="vault" onclick="show(\'vault\')"><span>🗂️</span>व्हॉल्ट</button>\n <button data-s="gst" onclick="show(\'gst\')"><span>🧾</span>GST</button>\n</nav>\n<datalist id="cats"><option>civil</option><option>road</option><option>building</option><option>water supply</option><option>electrical</option><option>sand</option><option>material supply</option><option>labour</option></datalist>\n<div id="toast"></div><dialog id="dlg"></dialog>\n\n<script>\nconst $=s=>document.querySelector(s);\nconst esc=s=>String(s??\'\').replace(/[&<>"\']/g,c=>({\'&\':\'&amp;\',\'<\':\'&lt;\',\'>\':\'&gt;\',\'"\':\'&quot;\',"\'":\'&#39;\'}[c]));\nconst inr=n=>n==null?\'—\':\'₹\'+Number(n).toLocaleString(\'en-IN\',{maximumFractionDigits:2});\nconst num=id=>{const v=$(\'#\'+id).value.trim();return v===\'\'?null:Number(v)};\nconst val=id=>$(\'#\'+id).value.trim();\nlet phone=localStorage.getItem(\'tb_phone\')||\'\';\nlet profile=JSON.parse(localStorage.getItem(\'tb_profile\')||\'{}\');\nlet vaultDocs=[], lastTenders=[], deferredInstall=null;\n\nfunction toast(m){const t=$(\'#toast\');t.textContent=m;t.style.display=\'block\';clearTimeout(toast.h);toast.h=setTimeout(()=>t.style.display=\'none\',3500)}\nfunction setPlan(d){const s=d.plan_status;$(\'#planBadge\').textContent=s===\'trial\'?`ट्रायल: दिवस ${d.trial_day}/${d.trial_days_total||15}`:s===\'expired\'?\'ट्रायल संपली\':s===\'vip\'?\'VIP\':s===\'basic\'?\'Basic\':\'—\'}\nasync function api(path,method=\'GET\',body){\n  let r;try{r=await fetch(path,{method,headers:{\'Content-Type\':\'application/json\'},body:body?JSON.stringify(body):undefined})}\n  catch(e){throw new Error(\'सर्व्हरशी संपर्क होत नाही. इंटरनेट तपासा; सर्व्हर झोपला असल्यास १ मिनिट थांबून पुन्हा करा.\')}\n  let d=null;try{d=await r.json()}catch(e){}\n  if(!r.ok){const det=d&&d.detail;\n    if(r.status===402&&det&&det.message_mr){if(det.plan_status)setPlan(det);const e=new Error(det.message_mr);e.paywall=true;throw e}\n    if(r.status===422&&Array.isArray(det))throw new Error(\'कृपया माहिती तपासा: \'+det.map(x=>((x.loc||[]).slice(-1)[0]||\'\')+\' — \'+x.msg).join(\'; \'));\n    throw new Error(typeof det===\'string\'?det:(det&&det.message_mr)||(\'त्रुटी (\'+r.status+\')\'))}\n  if(d&&d.plan_status)setPlan(d);return d}\nfunction fail(id,e){$(\'#\'+id).innerHTML=`<div class="${e.paywall?\'pay\':\'err\'}">${esc(e.message)}</div>`}\nfunction needPhone(){if(phone)return true;toast(\'आधी प्रोफाइलमध्ये तुमचा WhatsApp नंबर टाका\');show(\'profile\');return false}\nasync function busy(btn,fn){if(btn)btn.disabled=true;try{await fn()}finally{if(btn)btn.disabled=false}}\n\nfunction show(id){\n  document.querySelectorAll(\'.screen\').forEach(s=>s.classList.toggle(\'on\',s.id===\'s-\'+id));\n  document.querySelectorAll(\'nav button\').forEach(b=>b.classList.toggle(\'on\',b.dataset.s===id));\n  window.scrollTo(0,0);\n  if(id===\'approval\'&&phone)loadSubs();\n  if(id===\'vault\'&&phone)loadVault();\n  if(id===\'search\'&&!lastTenders.length)doSearch(true);\n}\n\n/* ---------- 1. Tender search ---------- */\nasync function doSearch(silent){\n  const p=new URLSearchParams();\n  [[\'q\',\'sf_q\'],[\'category\',\'sf_category\'],[\'district\',\'sf_district\'],[\'department\',\'sf_department\'],[\'min_cost\',\'sf_min_cost\'],[\'max_cost\',\'sf_max_cost\']].forEach(([k,i])=>{const v=val(i);if(v)p.set(k,v)});\n  try{const d=await api(\'/tenders/search?\'+p);lastTenders=d.tenders;\n    $(\'#searchRes\').innerHTML=d.tenders.length?`<p class="muted">${d.count} टेंडर सापडले</p>`+d.tenders.map((t,i)=>`<div class="card"><b>${esc(t.title)}</b>\n      <div class="muted">${esc(t.tender_id)} · ${esc(t.department)}</div>\n      <div class="kpi"><div><small>अंदाजित किंमत</small><b>${inr(t.estimated_cost)}</b></div><div><small>EMD</small><b>${inr(t.emd_amount)}</b></div></div>\n      <span class="chip">${esc(t.category)}</span> ${t.district?`<span class="chip">${esc(t.district)}</span>`:\'\'}\n      <div><button class="btn sm sec" onclick="toPredict(${i})">📈 बिड रेट</button><button class="btn sm sec" onclick="openAnalyze(${i})">📋 पात्रता तपासा</button><button class="btn sm" onclick="toApproval(${i})">✅ मंजुरी</button></div></div>`).join(\'\')\n      :\'<div class="info">या फिल्टरने कोणतेही टेंडर नाही. खाली "नवीन टेंडर जोडा" वापरून पोर्टलवरचे टेंडर जोडा.</div>\'}\n  catch(e){if(!silent)fail(\'searchRes\',e)}}\nasync function addTender(){if(!needPhone())return;\n  try{await api(\'/tenders\',\'POST\',{phone,tender_id:val(\'at_id\'),title:val(\'at_title\'),department:val(\'at_dept\'),category:val(\'at_cat\')||\'general\',district:val(\'at_dist\')||null,estimated_cost:num(\'at_cost\'),emd_amount:num(\'at_emd\')});\n    toast(\'टेंडर सेव्ह झाले\');[\'at_id\',\'at_title\',\'at_dept\',\'at_cat\',\'at_dist\',\'at_cost\',\'at_emd\'].forEach(i=>$(\'#\'+i).value=\'\');doSearch()}catch(e){toast(e.message)}}\nasync function importTenders(){\n  try{const d=await api(\'/discover-tenders\',\'POST\',{url:val(\'im_url\'),category:val(\'im_cat\')||null,district:val(\'im_dist\')||null,save:true});\n    $(\'#imRes\').innerHTML=`<div class="info">${d.count} ओळी सापडल्या, ${d.saved} नवीन सेव्ह झाल्या.</div>`;doSearch()}catch(e){fail(\'imRes\',e)}}\nfunction toPredict(i){const t=lastTenders[i];$(\'#pr_cat\').value=t.category;$(\'#pr_dept\').value=t.department;$(\'#pr_title\').value=t.title;$(\'#pr_est\').value=t.estimated_cost;show(\'predict\')}\nfunction toApproval(i){const t=lastTenders[i];$(\'#ap_id\').value=t.tender_id;$(\'#ap_title\').value=t.title;$(\'#ap_amt\').value=\'\';show(\'approval\')}\nasync function openAnalyze(i){\n  if(!needPhone())return;const t=lastTenders[i];await loadVault(true);\n  const d=$(\'#dlg\');d.innerHTML=`<h2>📋 पात्रता तपासणी</h2><p class="muted">${esc(t.title)}</p>\n   <label>निविदेत मागितलेली कागदपत्रे (प्रत्येक वेगळ्या ओळीत)</label><textarea id="an_docs" rows="5" placeholder="GST Registration&#10;PAN Card&#10;EPF Certificate"></textarea>\n   <div class="grid2"><div><label>किमान वर्ग</label><input id="an_class" placeholder="Class 1"></div><div><label>किमान उलाढाल (₹)</label><input id="an_turn" type="number"></div></div>\n   <p class="muted">तुमच्याकडे असलेली कागदपत्रे व्हॉल्टमधून घेतली जातात (${vaultDocs.length}).</p>\n   <button class="btn" id="an_go">तपासा</button><button class="btn sec" onclick="$(\'#dlg\').close()">बंद करा</button><div id="anRes"></div>`;\n  d.showModal();\n  $(\'#an_go\').onclick=()=>busy($(\'#an_go\'),async()=>{\n    const docs=val(\'an_docs\').split(\'\\n\').map(s=>s.trim()).filter(Boolean);\n    if(!docs.length){$(\'#anRes\').innerHTML=\'<div class="err">किमान एक कागदपत्र लिहा.</div>\';return}\n    try{const r=await api(\'/analyze-tender\',\'POST\',{vendor:{phone,name:profile.name||\'कंत्राटदार\',contractor_class:profile.contractor_class||null,categories:profile.categories||[],districts:profile.districts||[],annual_turnover:profile.annual_turnover??null,documents_held:vaultDocs.map(x=>x.doc_type)},\n      tender:{tender_id:t.tender_id,title:t.title,department:t.department,category:t.category,district:t.district,estimated_cost:t.estimated_cost,emd_amount:t.emd_amount,required_documents:docs,minimum_class:val(\'an_class\')||null,min_turnover:num(\'an_turn\')},send_whatsapp:false});\n      const a=r.analysis,v=a.eligible===true?[\'पात्र\',\'ok\']:a.eligible===false?[\'अपात्र / त्रुटी\',\'bad\']:[\'तपासणी अपूर्ण\',\'warn\'];\n      $(\'#anRes\').innerHTML=`<div class="card"><span class="chip ${v[1]}">${v[0]}</span>\n       ${a.missing_documents.length?`<h3>❌ कमी कागदपत्रे</h3><ul>${a.missing_documents.map(x=>`<li>${esc(x)}</li>`).join(\'\')}</ul>`:\'\'}\n       ${a.matched_documents.length?`<h3>✅ उपलब्ध</h3><ul>${a.matched_documents.map(x=>`<li>${esc(x)}</li>`).join(\'\')}</ul>`:\'\'}\n       ${a.issues.concat(a.unverified).map(x=>`<p>⚠️ ${esc(x)}</p>`).join(\'\')}</div>`}\n    catch(e){fail(\'anRes\',e)}})}\n\n/* ---------- 2. Bid rate predictor ---------- */\nasync function runPredict(){if(!needPhone())return;\n  const est=num(\'pr_est\');if(!val(\'pr_cat\')||!est){$(\'#predRes\').innerHTML=\'<div class="err">श्रेणी आणि अंदाजित किंमत आवश्यक आहे.</div>\';return}\n  try{const d=await api(\'/predict-bid-rate\',\'POST\',{phone,tender:{tender_id:\'ADHOC\',title:val(\'pr_title\')||\'बिड रेट चाचणी\',department:val(\'pr_dept\')||\'—\',category:val(\'pr_cat\'),estimated_cost:est},own_cost_estimate:num(\'pr_own\')});\n    const p=d.prediction;\n    if(!p.data_available){$(\'#predRes\').innerHTML=`<div class="card"><h2>${esc(p.message_mr)}</h2><p class="muted">सापडलेले नमुने: ${p.samples_found} (किमान ${p.minimum_samples_required} हवेत). Admin ने अवार्ड डेटा भरला की येथे अंदाज दिसेल.</p></div>`;return}\n    const L={aggressive:\'आक्रमक (जिंकण्याची शक्यता जास्त)\',recommended:\'सुचवलेला (अंदाजे L1)\',conservative:\'सावध (नफा जास्त)\'};\n    $(\'#predRes\').innerHTML=`<div class="card"><h2>${esc(p.predicted_l1_description_mr)}</h2><p>${esc(p.narrative_mr)}</p>\n      ${Object.entries(p.scenarios).map(([k,s])=>`<div class="pr"><b>${L[k]}</b><div class="kpi"><div><small>रेट</small><b>${s.percent_vs_estimate>0?\'+\':\'\'}${s.percent_vs_estimate}%</b></div><div><small>बिड रक्कम</small><b>${inr(s.bid_amount)}</b></div>\n      ${s.profit_margin_percent!=null?`<div><small>नफा</small><b>${inr(s.profit_amount)}</b></div><div><small>मार्जिन</small><b>${s.profit_margin_percent}%</b></div>`:\'\'}</div></div>`).join(\'\')}\n      ${p.warnings_mr.map(w=>`<div class="err">${esc(w)}</div>`).join(\'\')}\n      <p class="muted">आधार: ${p.data_basis.samples} अवार्ड्स · ${esc(p.data_basis.sources.join(\', \'))} · ${esc(p.data_basis.match_scope)}</p>\n      ${p.frequent_winners.length?`<h3>वारंवार जिंकणारे</h3>${p.frequent_winners.map(w=>`<div>${esc(w.name)} — ${w.wins}</div>`).join(\'\')}`:\'\'}</div>`}\n  catch(e){fail(\'predRes\',e)}}\n\n/* ---------- 3. Submission approval ---------- */\nconst ST={PENDING:[\'मंजुरी प्रलंबित\',\'warn\'],CANCELLED:[\'रद्द\',\'bad\'],APPROVED_AWAITING_PORTAL_SUBMISSION:[\'मंजूर — पोर्टल सबमिशन बाकी\',\'warn\'],SUBMITTED:[\'सबमिट झाले\',\'ok\'],APPROVED_SUBMISSION_FAILED:[\'सबमिशन अयशस्वी\',\'bad\']};\nasync function reqApproval(){if(!needPhone())return;\n  try{const d=await api(\'/request-submit-approval\',\'POST\',{phone,tender_id:val(\'ap_id\'),tender_title:val(\'ap_title\'),bid_amount:num(\'ap_amt\'),place_call:$(\'#ap_call\').checked});\n    const dry=(d.whatsapp&&d.whatsapp.mode===\'dry_run\')?\'<br>⚠️ Twilio जोडलेले नाही — WhatsApp/कॉल पाठवला गेला नाही. खाली ॲपमध्येच मंजुरी द्या.\':\'\';\n    $(\'#apRes\').innerHTML=`<div class="info">${esc(d.prompt_mr)}${dry}</div>`;loadSubs()}catch(e){fail(\'apRes\',e)}}\nasync function loadSubs(){\n  try{const d=await api(\'/submissions?phone=\'+encodeURIComponent(phone));\n    $(\'#subList\').innerHTML=d.submissions.length?d.submissions.map(s=>{const st=ST[s.status]||[s.status,\'\'];\n      return `<div class="card"><b>${esc(s.tender_title)}</b><div class="muted">${esc(s.tender_ref)} · ${inr(s.bid_amount)}</div><span class="chip ${st[1]}">${st[0]}</span>\n      ${s.detail?`<p class="muted">${esc(s.detail)}</p>`:\'\'}\n      ${s.status===\'PENDING\'?`<button class="btn sm ok" onclick="decide(${s.id},\'YES\')">होय, सबमिट करा</button><button class="btn sm bad" onclick="decide(${s.id},\'NO\')">नाही, रद्द करा</button>`:\'\'}</div>`}).join(\'\'):\'<div class="info">अजून कोणतेही सबमिशन नाही.</div>\'}\n  catch(e){fail(\'subList\',e)}}\nasync function decide(id,decision){\n  if(!confirm(decision===\'YES\'?\'खात्री आहे? बिड मंजूर होईल.\':\'हे सबमिशन रद्द करायचे?\'))return;\n  try{const r=await api(`/submissions/${id}/decision`,\'POST\',{phone,decision});toast(r.message_mr);loadSubs()}catch(e){toast(e.message)}}\n\n/* ---------- 4. Document vault ---------- */\nconst VS={valid:[\'वैध\',\'ok\'],expiring_soon:[\'लवकरच संपणार\',\'warn\'],expired:[\'संपले\',\'bad\'],no_expiry:[\'मुदत नाही\',\'\']};\nasync function loadVault(silent){\n  try{const d=await api(\'/vault/documents?phone=\'+encodeURIComponent(phone));vaultDocs=d.documents;\n    if(silent)return;\n    $(\'#vaultList\').innerHTML=d.documents.length?d.documents.map(x=>{const s=VS[x.status]||[x.status,\'\'];\n      return `<div class="pr"><b>${esc(x.doc_type)}</b> <span class="chip ${s[1]}">${s[0]}</span><div class="muted">${x.doc_number?\'क्र. \'+esc(x.doc_number)+\' · \':\'\'}${x.expiry_date?\'मुदत: \'+esc(x.expiry_date)+(x.days_left!=null?` (${x.days_left} दिवस)`:\'\'):\'\'}</div>\n      ${x.file_ref?`<a href="${esc(x.file_ref)}" target="_blank" rel="noopener">फाइल उघडा</a>`:\'\'}</div>`}).join(\'\'):\'<div class="info">व्हॉल्ट रिकामा आहे. खाली कागदपत्र जोडा. मुदत संपण्याच्या ३० दिवस आधी WhatsApp अलर्ट येतो.</div>\'}\n  catch(e){if(!silent)fail(\'vaultList\',e)}}\nasync function addDoc(){if(!needPhone())return;\n  try{await api(\'/vault/documents\',\'POST\',{phone,doc_type:val(\'vd_other\')||val(\'vd_type\'),doc_number:val(\'vd_num\')||null,expiry_date:val(\'vd_exp\')||null,file_ref:val(\'vd_ref\')||null});\n    toast(\'कागदपत्र जोडले\');[\'vd_other\',\'vd_num\',\'vd_exp\',\'vd_ref\'].forEach(i=>$(\'#\'+i).value=\'\');loadVault()}catch(e){toast(e.message)}}\n\n/* ---------- 5. GST advice ---------- */\nfunction addPurchase(){const d=document.createElement(\'div\');d.className=\'pr\';\n  d.innerHTML=`<input class="pd" placeholder="खरेदीचे नाव (उदा. सिमेंट)"><div class="grid2"><div><label>मूल्य (₹)</label><input class="pv" type="number" inputmode="decimal"></div><div><label>GST %</label><input class="pg" type="number" value="18" inputmode="decimal"></div></div>\n  <div class="row" style="margin-top:8px"><input type="checkbox" class="pe" checked><span>ITC पात्र</span><button class="btn sm sec" style="margin:0 0 0 auto" onclick="this.closest(\'.pr\').remove()">काढा</button></div>`;$(\'#g_purch\').appendChild(d)}\nasync function runGst(){if(!needPhone())return;\n  const purchases=[...document.querySelectorAll(\'#g_purch .pr\')].map(r=>({description:r.querySelector(\'.pd\').value.trim()||\'खरेदी\',taxable_value:Number(r.querySelector(\'.pv\').value||0),gst_rate_percent:Number(r.querySelector(\'.pg\').value||0),itc_eligible:r.querySelector(\'.pe\').checked})).filter(p=>p.taxable_value>0);\n  try{const d=await api(\'/get-tax-advice\',\'POST\',{phone,taxable_value:num(\'g_val\'),gst_rate_percent:num(\'g_rate\'),intra_state:val(\'g_intra\')===\'1\',purchases,gst_tds_applicable:$(\'#g_tds\').checked});\n    const rows=d.ca_ready_breakdown;\n    $(\'#gstRes\').innerHTML=`<div class="card"><h2>निकाल</h2><p>${esc(d.summary_mr)}</p>\n     <div class="kpi"><div><small>आउटपुट GST</small><b>${inr(d.output_tax.total)}</b></div><div><small>पात्र ITC</small><b>${inr(d.itc.eligible_total)}</b></div><div><small>निव्वळ GST देय</small><b>${inr(d.net_gst_payable)}</b></div><div><small>मिळणारी रक्कम</small><b>${inr(d.expected_receipt)}</b></div></div>\n     ${rows?`<h3>सीए-रेडी तपशील</h3><table>${rows.map(r=>`<tr><td>${esc(r.particular)}</td><td>${inr(r.amount)}</td></tr>`).join(\'\')}</table>\n       <button class="btn sec" onclick=\'shareGst(${JSON.stringify(JSON.stringify(rows))})\'>📤 सीए ला शेअर करा</button>`\n       :`<div class="pay">${esc((d.ca_ready_export||{}).message_mr||\'फक्त ड्राफ्ट उपलब्ध\')}</div>`}\n     <h3>टॅक्स नियोजन सूचना</h3><ul>${d.strategies_mr.map(s=>`<li>${esc(s)}</li>`).join(\'\')}</ul><p class="muted">${esc(d.disclaimer_mr)}</p></div>`}\n  catch(e){fail(\'gstRes\',e)}}\nfunction shareGst(json){const rows=JSON.parse(json);const text=\'GST हिशोब (TenderBot AI)\\n\'+rows.map(r=>`${r.particular.trim()}: ${inr(r.amount)}`).join(\'\\n\');\n  if(navigator.share)navigator.share({text}).catch(()=>{});else{navigator.clipboard.writeText(text);toast(\'कॉपी केले\')}}\n\n/* ---------- Profile ---------- */\nfunction fillProfile(){$(\'#pf_phone\').value=phone;$(\'#pf_name\').value=profile.name||\'\';$(\'#pf_class\').value=profile.contractor_class||\'\';$(\'#pf_turn\').value=profile.annual_turnover??\'\';$(\'#pf_cats\').value=(profile.categories||[]).join(\', \');$(\'#pf_dists\').value=(profile.districts||[]).join(\', \')}\nconst list=s=>s.split(\',\').map(x=>x.trim()).filter(Boolean);\nasync function saveProfile(){\n  const p=val(\'pf_phone\');if(!p){$(\'#pfRes\').innerHTML=\'<div class="err">नंबर आवश्यक आहे.</div>\';return}\n  try{const d=await api(\'/me\',\'POST\',{phone:p,name:val(\'pf_name\')||null,contractor_class:val(\'pf_class\')||null,annual_turnover:num(\'pf_turn\'),categories:list(val(\'pf_cats\')),districts:list(val(\'pf_dists\'))});\n    phone=d.phone;profile={name:d.name,contractor_class:d.contractor_class,annual_turnover:d.annual_turnover,categories:d.categories,districts:d.districts};\n    localStorage.setItem(\'tb_phone\',phone);localStorage.setItem(\'tb_profile\',JSON.stringify(profile));\n    $(\'#pfRes\').innerHTML=\'<div class="info">प्रोफाइल सेव्ह झाले ✔</div>\';toast(\'सेव्ह झाले\')}catch(e){fail(\'pfRes\',e)}}\nwindow.addEventListener(\'beforeinstallprompt\',e=>{e.preventDefault();deferredInstall=e;$(\'#installBtn\').style.display=\'block\'});\nfunction installApp(){if(deferredInstall){deferredInstall.prompt();deferredInstall=null}}\n\n/* ---------- start ---------- */\nif(\'serviceWorker\' in navigator)navigator.serviceWorker.register(\'/sw.js\').catch(()=>{});\naddPurchase();fillProfile();\nif(phone){api(\'/me?phone=\'+encodeURIComponent(phone)).then(d=>{profile={name:d.name,contractor_class:d.contractor_class,annual_turnover:d.annual_turnover,categories:d.categories,districts:d.districts};localStorage.setItem(\'tb_profile\',JSON.stringify(profile));fillProfile()}).catch(()=>{});show(\'search\')}\nelse show(\'profile\');\n</script></body></html>\n"""\n',
    'agents/__init__.py': '"""Shared helpers for all TenderBot agents (LLM access, formatting)."""\nfrom __future__ import annotations\n\nimport json\nimport logging\nfrom datetime import date\n\nfrom config import get_settings\n\nlogger = logging.getLogger("tenderbot")\n\n\nclass LLMUnavailable(RuntimeError):\n    """Raised when GPT-4o is requested but OPENAI_API_KEY is not configured."""\n\n\ndef llm_available() -> bool:\n    return bool(get_settings().openai_api_key.strip())\n\n\ndef _chat(json_mode: bool):\n    if not llm_available():\n        raise LLMUnavailable("OPENAI_API_KEY सेट केलेली नाही.")\n    from langchain_openai import ChatOpenAI\n\n    settings = get_settings()\n    llm = ChatOpenAI(\n        model=settings.openai_model,\n        api_key=settings.openai_api_key,\n        temperature=0,\n        timeout=60,\n        max_retries=2,\n    )\n    return llm.bind(response_format={"type": "json_object"}) if json_mode else llm\n\n\ndef llm_text(system: str, user: str) -> str:\n    from langchain_core.messages import HumanMessage, SystemMessage\n\n    response = _chat(False).invoke([SystemMessage(content=system), HumanMessage(content=user)])\n    return str(response.content).strip()\n\n\ndef llm_json(system: str, user: str) -> dict:\n    from langchain_core.messages import HumanMessage, SystemMessage\n\n    response = _chat(True).invoke([SystemMessage(content=system), HumanMessage(content=user)])\n    return json.loads(str(response.content))\n\n\ndef format_inr(amount: float | int | None) -> str:\n    """Format a number with Indian digit grouping, e.g. 12,34,567.50 with the rupee sign."""\n    if amount is None:\n        return "—"\n    value = round(float(amount), 2)\n    negative = value < 0\n    value = abs(value)\n    whole = int(value)\n    paise = int(round((value - whole) * 100))\n    digits = str(whole)\n    if len(digits) > 3:\n        head, tail = digits[:-3], digits[-3:]\n        groups: list[str] = []\n        while len(head) > 2:\n            groups.insert(0, head[-2:])\n            head = head[:-2]\n        if head:\n            groups.insert(0, head)\n        digits = ",".join(groups + [tail])\n    if paise:\n        digits += f".{paise:02d}"\n    return ("-" if negative else "") + "₹" + digits\n\n\ndef fmt_date(value: date | None) -> str:\n    return value.strftime("%d/%m/%Y") if value else "—"\n',
    'agents/scraper_agent.py': '"""Tender discovery + historical awarded-tender ingestion from PUBLIC portals (Mahatenders / CPPP).\n\nThe scraper only reads publicly accessible HTML result tables (or saved HTML / JSON records you supply).\nIt does not bypass captchas or logins; portal pages that need them must be saved/exported by you and ingested.\n"""\nfrom __future__ import annotations\n\nimport hashlib\nimport re\nfrom datetime import date, datetime\nfrom urllib.parse import urlparse\n\nimport httpx\nfrom bs4 import BeautifulSoup\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom agents import logger\nfrom config import get_settings\nfrom database import AwardedTender\n\n# Ordered: first match wins per column. Order matters ("awarded value" must not become "award date").\nHEADER_KEYS: list[tuple[str, tuple[str, ...]]] = [\n    ("estimated_cost", ("estimated", "tender value", "est. cost", "estimate", "engineer")),\n    ("awarded_amount", ("awarded value", "award value", "contract value", "awarded amount", "accepted", "l1 value", "contract amount")),\n    ("winner_name", ("awarded to", "winner", "successful", "contractor name", "bidder name", "vendor")),\n    ("award_date", ("award date", "date of award", "aoc date", "awarded on", "aoc")),\n    ("tender_ref", ("tender id", "tender ref", "reference", "tender no", "nit no", "e-tender")),\n    ("department", ("department", "organisation", "organization", "office")),\n    ("title", ("title", "name of work", "work", "description")),\n]\n\nDATE_FORMATS = ("%d-%m-%Y", "%d/%m/%Y", "%Y-%m-%d", "%d-%b-%Y", "%d %b %Y", "%d-%B-%Y")\n\n\ndef parse_amount(text: str | float | int | None) -> float | None:\n    if text is None:\n        return None\n    if isinstance(text, (int, float)):\n        return float(text)\n    cleaned = re.sub(r"[^0-9.]", "", str(text).replace(",", ""))\n    if cleaned.count(".") > 1 or cleaned in ("", "."):\n        return None\n    return float(cleaned)\n\n\ndef parse_date(text: str | date | None) -> date | None:\n    if isinstance(text, date):\n        return text\n    if not text:\n        return None\n    for fmt in DATE_FORMATS:\n        try:\n            return datetime.strptime(str(text).strip(), fmt).date()\n        except ValueError:\n            continue\n    return None\n\n\ndef parse_tables(html: str, required: tuple[str, ...]) -> list[dict]:\n    """Extract rows from HTML tables whose header row maps to every key in `required`."""\n    soup = BeautifulSoup(html, "html.parser")\n    out: list[dict] = []\n    for table in soup.find_all("table"):\n        rows = table.find_all("tr")\n        if len(rows) < 2:\n            continue\n        headers = [c.get_text(" ", strip=True).lower() for c in rows[0].find_all(["th", "td"])]\n        mapping: dict[int, str] = {}\n        for idx, header in enumerate(headers):\n            for key, needles in HEADER_KEYS:\n                if key in mapping.values():\n                    continue\n                if any(n in header for n in needles):\n                    mapping[idx] = key\n                    break\n        if not all(key in mapping.values() for key in required):\n            continue\n        for row in rows[1:]:\n            cells = [c.get_text(" ", strip=True) for c in row.find_all(["td", "th"])]\n            record = {key: cells[idx] for idx, key in mapping.items() if idx < len(cells)}\n            if record:\n                out.append(record)\n    return out\n\n\ndef normalise_record(raw: dict, source: str, source_url: str | None = None,\n                     default_category: str | None = None, default_department: str | None = None) -> dict | None:\n    """Convert a raw row/dict into an AwardedTender-ready record, or None if unusable."""\n    estimated = parse_amount(raw.get("estimated_cost"))\n    awarded = parse_amount(raw.get("awarded_amount"))\n    if not estimated or not awarded or estimated <= 0 or awarded <= 0:\n        return None\n    title = (raw.get("title") or "").strip() or None\n    winner = (raw.get("winner_name") or "").strip() or None\n    ref = (raw.get("tender_ref") or "").strip()\n    if not ref:\n        digest = hashlib.sha1(f"{title}|{winner}|{awarded}".encode("utf-8")).hexdigest()[:12]\n        ref = f"{source}-{digest}"\n    return {\n        "tender_ref": ref,\n        "title": title,\n        "department": (raw.get("department") or default_department or "").strip() or None,\n        "category": (raw.get("category") or default_category or "").strip() or None,\n        "district": (raw.get("district") or "").strip() or None,\n        "estimated_cost": estimated,\n        "awarded_amount": awarded,\n        "percent_vs_estimate": round((awarded - estimated) / estimated * 100, 2),\n        "winner_name": winner,\n        "award_date": parse_date(raw.get("award_date")),\n        "source": source,\n        "source_url": raw.get("source_url") or source_url,\n    }\n\n\ndef ingest_records(db: Session, records: list[dict]) -> dict:\n    inserted = duplicates = 0\n    for rec in records:\n        exists = db.scalar(\n            select(AwardedTender.id).where(\n                AwardedTender.tender_ref == rec["tender_ref"], AwardedTender.source == rec["source"]\n            )\n        )\n        if exists:\n            duplicates += 1\n            continue\n        db.add(AwardedTender(**rec))\n        inserted += 1\n    db.commit()\n    return {"inserted": inserted, "duplicates_skipped": duplicates}\n\n\ndef _assert_allowed_host(url: str) -> None:\n    host = (urlparse(url).hostname or "").lower()\n    allowed = get_settings().scrape_hosts\n    if urlparse(url).scheme not in ("http", "https") or not any(host == h or host.endswith("." + h) for h in allowed):\n        raise ValueError(f"हा होस्ट परवानगी यादीत नाही. परवानगी असलेले: {\', \'.join(allowed)}")\n\n\ndef fetch_html(url: str) -> str:\n    _assert_allowed_host(url)\n    headers = {"User-Agent": "Mozilla/5.0 (TenderBotAI public-data reader)"}\n    response = httpx.get(url, headers=headers, timeout=30, follow_redirects=True)\n    response.raise_for_status()\n    return response.text\n\n\ndef ingest_awarded_from_html(db: Session, html: str, source: str, source_url: str | None = None,\n                             category: str | None = None, department: str | None = None) -> dict:\n    rows = parse_tables(html, required=("estimated_cost", "awarded_amount"))\n    records = [r for r in (normalise_record(row, source, source_url, category, department) for row in rows) if r]\n    result = ingest_records(db, records)\n    result.update({"rows_found": len(rows), "usable_records": len(records)})\n    logger.info("awarded ingest from %s: %s", source_url or "html", result)\n    return result\n\n\ndef ingest_awarded_from_url(db: Session, url: str, source: str, category: str | None = None,\n                            department: str | None = None) -> dict:\n    return ingest_awarded_from_html(db, fetch_html(url), source, url, category, department)\n\n\ndef ingest_awarded_json(db: Session, items: list[dict], source: str, default_category: str | None = None) -> dict:\n    records = [r for r in (normalise_record(i, source, i.get("source_url"), default_category) for i in items) if r]\n    result = ingest_records(db, records)\n    result.update({"received": len(items), "usable_records": len(records)})\n    return result\n\n\ndef discover_active_tenders(url: str) -> list[dict]:\n    """Read a public active-tenders listing page and return rows that expose an estimated value."""\n    rows = parse_tables(fetch_html(url), required=("estimated_cost",))\n    results = []\n    for row in rows:\n        value = parse_amount(row.get("estimated_cost"))\n        if value:\n            results.append({**row, "estimated_cost": value, "source_url": url})\n    return results\n',
    'agents/analyzer_agent.py': '"""Eligibility analysis: required-document gap check, class/turnover checks, WhatsApp alert text."""\nfrom __future__ import annotations\n\nimport re\n\nfrom agents import format_inr, llm_json\n\nALIAS_TOKENS: dict[str, set[str]] = {\n    "gst": {"gst", "gstin"},\n    "pan": {"pan"},\n    "epf": {"epf", "pf", "provident"},\n    "esic": {"esic", "esi"},\n    "pwd": {"pwd", "enlistment", "mpwd"},\n    "itr": {"itr"},\n    "solvency": {"solvency"},\n    "turnover": {"turnover"},\n    "labour": {"labour", "labor"},\n    "udyam": {"udyam", "msme"},\n    "dsc": {"dsc"},\n    "profession_tax": {"ptrc", "professional"},\n}\nROMAN = {"i": 1, "ii": 2, "iii": 3, "iv": 4, "v": 5, "vi": 6, "vii": 7}\n\nEXTRACTION_SYSTEM_PROMPT = (\n    "You extract eligibility requirements from Indian government tender text (may be Marathi or English). "\n    "Return ONLY a JSON object with keys: required_documents (list of short document names), "\n    "minimum_class (string or null), min_turnover (number in INR or null), emd_amount (number in INR or null). "\n    "Extract ONLY what is explicitly written in the text. Never guess. Use null or an empty list when absent."\n)\n\n\ndef _tokens(text: str) -> set[str]:\n    return {t for t in re.split(r"[\\s,;:/()\\-_.]+", text.lower()) if t}\n\n\ndef _canonical(doc: str) -> str | None:\n    tokens = _tokens(doc)\n    for key, aliases in ALIAS_TOKENS.items():\n        if tokens & aliases:\n            return key\n    return None\n\n\ndef _norm(doc: str) -> str:\n    return " ".join(sorted(_tokens(doc)))\n\n\ndef parse_class(text: str | None) -> int | None:\n    """\'Class 1\', \'Class-I\', \'वर्ग 2\' -> 1, 1, 2. Lower number = higher class."""\n    if not text:\n        return None\n    match = re.search(r"(\\d+)", text)\n    if match:\n        number = int(match.group(1))\n        return number if 1 <= number <= 9 else None\n    match = re.search(r"\\b(vii|vi|iii|ii|iv|v|i)\\b", text.lower())\n    return ROMAN.get(match.group(1)) if match else None\n\n\ndef extract_requirements(tender_text: str) -> dict:\n    """GPT-4o extraction of eligibility requirements from raw tender text."""\n    data = llm_json(EXTRACTION_SYSTEM_PROMPT, tender_text[:24000])\n    return {\n        "required_documents": [str(d).strip() for d in (data.get("required_documents") or []) if str(d).strip()],\n        "minimum_class": data.get("minimum_class"),\n        "min_turnover": data.get("min_turnover"),\n        "emd_amount": data.get("emd_amount"),\n    }\n\n\ndef gap_analysis(required_documents: list[str], documents_held: list[str], contractor_class: str | None,\n                 minimum_class: str | None, annual_turnover: float | None, min_turnover: float | None) -> dict:\n    held_canon = {c for c in (_canonical(d) for d in documents_held) if c}\n    held_norm = {_norm(d) for d in documents_held}\n\n    matched, missing = [], []\n    for doc in required_documents:\n        canon = _canonical(doc)\n        if (canon and canon in held_canon) or _norm(doc) in held_norm:\n            matched.append(doc)\n        else:\n            missing.append(doc)\n\n    issues: list[str] = []\n    unverified: list[str] = []\n\n    required_class = parse_class(minimum_class)\n    if minimum_class:\n        have = parse_class(contractor_class)\n        if required_class is None:\n            unverified.append(f"किमान वर्ग \'{minimum_class}\' नीट समजला नाही — निविदा तपासा.")\n        elif have is None:\n            unverified.append(f"किमान वर्ग {minimum_class} आवश्यक आहे; तुमचा वर्ग प्रोफाइलमध्ये नाही.")\n        elif have > required_class:\n            issues.append(f"तुमचा वर्ग ({contractor_class}) आवश्यक वर्गापेक्षा ({minimum_class}) कमी आहे.")\n\n    if min_turnover:\n        if annual_turnover is None:\n            unverified.append(f"किमान उलाढाल {format_inr(min_turnover)} आवश्यक आहे; तुमची उलाढाल प्रोफाइलमध्ये नाही.")\n        elif annual_turnover < min_turnover:\n            issues.append(\n                f"तुमची उलाढाल {format_inr(annual_turnover)} आहे; आवश्यक किमान {format_inr(min_turnover)}."\n            )\n\n    if missing or issues:\n        eligible: bool | None = False\n    elif unverified:\n        eligible = None\n    else:\n        eligible = True\n\n    return {\n        "eligible": eligible,\n        "matched_documents": matched,\n        "missing_documents": missing,\n        "issues": issues,\n        "unverified": unverified,\n    }\n\n\ndef build_whatsapp_alert(tender: dict, analysis: dict) -> str:\n    lines = [\n        "🏗️ *TenderBot AI — टेंडर विश्लेषण*",\n        f"टेंडर: {tender[\'title\']} ({tender[\'tender_id\']})",\n        f"विभाग: {tender[\'department\']}",\n        f"अंदाजित किंमत: {format_inr(tender[\'estimated_cost\'])}",\n    ]\n    if tender.get("emd_amount"):\n        lines.append(f"EMD: {format_inr(tender[\'emd_amount\'])}")\n    lines.append("")\n    lines.append(f"✅ उपलब्ध कागदपत्रे: {len(analysis[\'matched_documents\'])}")\n    if analysis["missing_documents"]:\n        lines.append("❌ कमी असलेली कागदपत्रे:")\n        lines.extend(f"  • {d}" for d in analysis["missing_documents"])\n    for issue in analysis["issues"]:\n        lines.append(f"⚠️ {issue}")\n    for note in analysis["unverified"]:\n        lines.append(f"ℹ️ {note}")\n    lines.append("")\n    verdict = {\n        True: "निष्कर्ष: भाऊ, तुम्ही या टेंडरसाठी पात्र दिसता. बिड रेट तपासायचा का?",\n        False: "निष्कर्ष: भाऊ, वरील त्रुटी दूर केल्याशिवाय हे टेंडर भरणे धोक्याचे आहे.",\n        None: "निष्कर्ष: काही अटी तपासता आल्या नाहीत; प्रोफाइल पूर्ण करा किंवा निविदा तपासा.",\n    }[analysis["eligible"]]\n    lines.append(verdict)\n    return "\\n".join(lines)\n',
    'agents/competitor_agent.py': '"""Competitor AI & L1 rate prediction.\n\nSTRICT DATA RULE: uses ONLY public already-awarded tender results stored in AwardedTender\n(Mahatenders / CPPP). If there are not enough samples it answers "जुना डेटा उपलब्ध नाही" — never guesses.\nPercentages are relative to the tender\'s estimated cost (SSR-based estimate): negative = below, positive = above.\n"""\nfrom __future__ import annotations\n\nimport statistics\nfrom collections import Counter\n\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom agents import format_inr, llm_available, llm_text, logger\nfrom config import get_settings\nfrom database import AwardedTender\nfrom system_prompt import MASTER_SYSTEM_PROMPT, OLD_DATA_MSG_MR\n\n\ndef percentile(values: list[float], pct: float) -> float:\n    ordered = sorted(values)\n    if len(ordered) == 1:\n        return ordered[0]\n    pos = (len(ordered) - 1) * pct / 100\n    low = int(pos)\n    high = min(low + 1, len(ordered) - 1)\n    return ordered[low] + (ordered[high] - ordered[low]) * (pos - low)\n\n\ndef _describe(pct: float) -> str:\n    if pct < 0:\n        return f"SSR/अंदाजित दरापेक्षा {abs(pct):.1f}% कमी"\n    if pct > 0:\n        return f"SSR/अंदाजित दरापेक्षा {pct:.1f}% जास्त"\n    return "SSR/अंदाजित दराइतका"\n\n\ndef _fetch(db: Session, category: str, department: str | None) -> tuple[list[AwardedTender], str]:\n    base = select(AwardedTender).where(func.lower(AwardedTender.category).like(f"%{category.lower().strip()}%"))\n    min_samples = get_settings().min_history_samples\n    if department:\n        rows = list(db.scalars(base.where(func.lower(AwardedTender.department).like(f"%{department.lower().strip()}%"))))\n        if len(rows) >= min_samples:\n            return rows, "विभाग + श्रेणी"\n    return list(db.scalars(base)), "श्रेणी"\n\n\ndef predict_l1(db: Session, category: str, department: str | None, estimated_cost: float,\n               own_cost_estimate: float | None = None) -> dict:\n    min_samples = get_settings().min_history_samples\n    rows, scope = _fetch(db, category, department)\n\n    # Prefer similar-size tenders when that still leaves enough samples.\n    banded = [r for r in rows if 0.5 * estimated_cost <= r.estimated_cost <= 2 * estimated_cost]\n    if len(banded) >= min_samples:\n        rows, scope = banded, scope + " + समान किमतीची रेंज (०.५x–२x)"\n\n    if len(rows) < min_samples:\n        return {\n            "data_available": False,\n            "samples_found": len(rows),\n            "minimum_samples_required": min_samples,\n            "message_mr": OLD_DATA_MSG_MR,\n        }\n\n    pcts = [r.percent_vs_estimate for r in rows]\n    median = round(statistics.median(pcts), 2)\n    aggressive = round(percentile(pcts, 25), 2)   # lower (more below SSR) = more aggressive\n    conservative = round(percentile(pcts, 75), 2)\n    dated = [r.award_date for r in rows if r.award_date]\n\n    def bid_for(p: float) -> float:\n        return round(estimated_cost * (1 + p / 100), 2)\n\n    scenarios = {}\n    for label, p in (("aggressive", aggressive), ("recommended", median), ("conservative", conservative)):\n        item = {"percent_vs_estimate": p, "bid_amount": bid_for(p), "description_mr": _describe(p)}\n        if own_cost_estimate:\n            amount = bid_for(p)\n            item["profit_amount"] = round(amount - own_cost_estimate, 2)\n            item["profit_margin_percent"] = round((amount - own_cost_estimate) / amount * 100, 2)\n        scenarios[label] = item\n\n    winners = Counter(r.winner_name for r in rows if r.winner_name).most_common(5)\n    result = {\n        "data_available": True,\n        "predicted_l1_percent": median,\n        "predicted_l1_description_mr": _describe(median),\n        "scenarios": scenarios,\n        "data_basis": {\n            "samples": len(rows),\n            "match_scope": scope,\n            "sources": sorted({r.source for r in rows}),\n            "award_date_range": [min(dated).isoformat(), max(dated).isoformat()] if dated else None,\n            "winning_percent_min": round(min(pcts), 2),\n            "winning_percent_max": round(max(pcts), 2),\n        },\n        "frequent_winners": [{"name": n, "wins": c} for n, c in winners],\n        "warnings_mr": [],\n    }\n\n    if own_cost_estimate:\n        breakeven = round((own_cost_estimate / estimated_cost - 1) * 100, 2)\n        result["breakeven_percent_vs_estimate"] = breakeven\n        if median < breakeven:\n            result["warnings_mr"].append(\n                f"सावधान: अंदाजे L1 ({median:+.1f}%) तुमच्या ब्रेक-इव्हन ({breakeven:+.1f}%) पेक्षा कमी आहे — "\n                "या दराने बिड भरल्यास तोटा होईल."\n            )\n    result["narrative_mr"] = _narrative(result, estimated_cost, own_cost_estimate)\n    return result\n\n\ndef _narrative(result: dict, estimated_cost: float, own_cost: float | None) -> str:\n    basis = result["data_basis"]\n    base = (\n        f"मागील {basis[\'samples\']} सार्वजनिक अवार्ड्सनुसार ({\', \'.join(basis[\'sources\'])}) विजेती बोली साधारण "\n        f"{result[\'predicted_l1_description_mr\']} राहिली आहे (अंदाजे L1: {result[\'predicted_l1_percent\']:+.1f}%). "\n        f"या दराने बिड रक्कम ≈ {format_inr(result[\'scenarios\'][\'recommended\'][\'bid_amount\'])}."\n    )\n    if own_cost is not None:\n        margin = result["scenarios"]["recommended"].get("profit_margin_percent")\n        if margin is not None:\n            base += f" तुमच्या खर्च अंदाजानुसार नफा मार्जिन ≈ {margin:.1f}%."\n    if not llm_available():\n        return base\n    try:\n        system = (\n            MASTER_SYSTEM_PROMPT\n            + "\\nफक्त खाली दिलेले आकडे वापरून २-३ वाक्यांचा मराठी सारांश लिही. नवीन कोणताही आकडा किंवा नाव जोडू नकोस."\n        )\n        return llm_text(system, base)\n    except Exception as exc:  # fall back to the deterministic text\n        logger.warning("narrative LLM failed: %s", exc)\n        return base\n',
    'agents/bg_emd_agent.py': '"""1-Click EMD & Bank Guarantee document kit (checklist + bank request letter + WhatsApp summary).\n\nThe checklist is the common set banks ask for; the tender\'s own conditions and your bank\'s rules prevail.\n"""\nfrom __future__ import annotations\n\nfrom datetime import date\n\nfrom agents import fmt_date, format_inr\n\nBG_KINDS = {\n    "EMD_BG": "बयाना रक्कम (EMD) बँक गॅरंटी",\n    "PERFORMANCE_BG": "परफॉर्मन्स बँक गॅरंटी",\n}\n\nCOMMON_DOCUMENTS = [\n    "बँक गॅरंटी / EMD साठी विनंती पत्र (खाली तयार)",\n    "टेंडर नोटीस / निविदा सूचनेची प्रत (EMD/BG अटींसह)",\n    "फर्मचे PAN कार्ड आणि GST प्रमाणपत्र",\n    "फर्मचा KYC (पत्ता पुरावा, भागीदार/मालकाचे ओळखपत्र)",\n    "चालू खात्याचे (Current Account) तपशील",\n    "मागील आर्थिक वर्षाचे ऑडिटेड बॅलन्स शीट / ITR",\n    "क्रेडिट/ओव्हरड्राफ्ट लिमिट मंजुरी पत्र (असल्यास)",\n    "वर्क ऑर्डर / स्वीकृती पत्र (परफॉर्मन्स BG साठी)",\n]\n\n\ndef build_kit(contractor_name: str, tender_ref: str, tender_title: str, department: str, bg_type: str,\n              guarantee_amount: float, validity_months: int, bank_name: str | None = None,\n              branch: str | None = None, account_number_last4: str | None = None,\n              beneficiary: str | None = None, today: date | None = None) -> dict:\n    today = today or date.today()\n    kind = BG_KINDS[bg_type]\n    beneficiary = beneficiary or department\n\n    documents = list(COMMON_DOCUMENTS)\n    if bg_type == "PERFORMANCE_BG":\n        documents.append("करारनामा / कार्यारंभ आदेशाची प्रत")\n\n    to_line = f"व्यवस्थापक, {bank_name}" + (f", {branch} शाखा" if branch else "") if bank_name else "शाखा व्यवस्थापक, संबंधित बँक"\n    acct = f"\\nखाते क्रमांक (शेवटचे ४ अंक): {account_number_last4}" if account_number_last4 else ""\n\n    letter = (\n        f"प्रति,\\n{to_line}\\n\\nदिनांक: {fmt_date(today)}\\n\\n"\n        f"विषय: {kind} जारी करणेबाबत विनंती — {tender_ref}\\n\\n"\n        f"महोदय,\\n\\n"\n        f"आम्ही, {contractor_name}, आपल्या बँकेचे ग्राहक आहोत.{acct}\\n"\n        f"आम्ही \'{tender_title}\' (निविदा क्र. {tender_ref}) या कामासाठी {department} यांच्याकडे निविदा सादर करीत आहोत. "\n        f"निविदेतील अटींनुसार {format_inr(guarantee_amount)} रकमेची {kind} {beneficiary} यांच्या नावे "\n        f"{validity_months} महिन्यांच्या वैधतेसह जारी करण्याची कृपा करावी.\\n\\n"\n        f"आवश्यक कागदपत्रे सोबत जोडली आहेत. नियमानुसार लागणारे मार्जिन/शुल्क भरण्यास आम्ही तयार आहोत.\\n\\n"\n        f"आपला विश्वासू,\\n{contractor_name}\\n(अधिकृत स्वाक्षरी व शिक्का)"\n    )\n\n    whatsapp = (\n        f"🏦 *{kind} किट तयार*\\nटेंडर: {tender_title} ({tender_ref})\\n"\n        f"रक्कम: {format_inr(guarantee_amount)} | वैधता: {validity_months} महिने\\n\\n"\n        "बँकेत न्यायची कागदपत्रे:\\n" + "\\n".join(f"{i}. {d}" for i, d in enumerate(documents, 1)) +\n        "\\n\\nटीप: बँकेचे नियम आणि निविदेतील अटी अंतिम समजाव्यात."\n    )\n    return {\n        "guarantee_type": kind,\n        "guarantee_amount": guarantee_amount,\n        "validity_months": validity_months,\n        "document_checklist": documents,\n        "bank_request_letter_mr": letter,\n        "whatsapp_message": whatsapp,\n        "note_mr": "ही यादी सर्वसाधारण आहे; तुमच्या बँकेकडून आणि निविदेतील अटींनुसार खात्री करा.",\n    }\n',
    'agents/marketplace_agent.py': '"""Sub-contractor / material / labour marketplace.\n\nSTRICT DATA RULE: contacts and rates come ONLY from the Internal Verified Vendor Database (VerifiedVendor).\nIf nothing matches, say so — never invent a vendor, number or rate.\n"""\nfrom __future__ import annotations\n\nfrom datetime import date\n\nfrom sqlalchemy import func, select\nfrom sqlalchemy.orm import Session\n\nfrom agents import format_inr\nfrom database import VerifiedVendor\nfrom system_prompt import NO_VENDOR_MSG_MR\n\n\ndef search_vendors(db: Session, category: str, district: str | None = None, limit: int = 10) -> dict:\n    stmt = select(VerifiedVendor).where(func.lower(VerifiedVendor.category).like(f"%{category.lower().strip()}%"))\n    if district:\n        stmt = stmt.where(func.lower(VerifiedVendor.district) == district.lower().strip())\n    vendors = list(db.scalars(stmt.order_by(VerifiedVendor.last_verified_on.desc()).limit(limit)))\n    if not vendors:\n        return {"found": 0, "vendors": [], "message_mr": NO_VENDOR_MSG_MR, "source": "Internal Verified Vendor Database"}\n    items = []\n    for v in vendors:\n        rate_text = f"{format_inr(v.rate)}" + (f" / {v.rate_unit}" if v.rate_unit else "") if v.rate is not None else None\n        items.append({\n            "name": v.name, "category": v.category, "district": v.district, "phone": v.phone,\n            "rate": v.rate, "rate_text": rate_text, "last_verified_on": v.last_verified_on.isoformat(),\n        })\n    return {"found": len(items), "vendors": items, "source": "Internal Verified Vendor Database"}\n\n\ndef add_vendor(db: Session, name: str, category: str, district: str, phone: str, rate: float | None,\n               rate_unit: str | None, verified_by: str | None, last_verified_on: date | None = None) -> VerifiedVendor:\n    vendor = VerifiedVendor(\n        name=name, category=category, district=district, phone=phone, rate=rate, rate_unit=rate_unit,\n        verified_by=verified_by, last_verified_on=last_verified_on or date.today(),\n    )\n    db.add(vendor)\n    db.commit()\n    db.refresh(vendor)\n    return vendor\n',
    'agents/vault_agent.py': '"""VIP document vault with auto-renewal alerts (PWD licence, Class-1 certificate, EPF, GST ...)."""\nfrom __future__ import annotations\n\nfrom datetime import date, timedelta\n\nfrom sqlalchemy import select\nfrom sqlalchemy.orm import Session\n\nfrom agents import fmt_date, logger\nfrom agents.communication_agent import send_whatsapp\nfrom config import get_settings\nfrom database import Contractor, VaultDocument, check_access\n\n\ndef add_document(db: Session, contractor: Contractor, doc_type: str, doc_number: str | None,\n                 expiry_date: date | None, file_ref: str | None) -> VaultDocument:\n    doc = VaultDocument(contractor_id=contractor.id, doc_type=doc_type, doc_number=doc_number,\n                        expiry_date=expiry_date, file_ref=file_ref)\n    db.add(doc)\n    db.commit()\n    db.refresh(doc)\n    return doc\n\n\ndef serialize(doc: VaultDocument, today: date | None = None) -> dict:\n    today = today or date.today()\n    days_left = (doc.expiry_date - today).days if doc.expiry_date else None\n    status = "no_expiry" if days_left is None else "expired" if days_left < 0 else "expiring_soon" if days_left <= get_settings().expiry_alert_days else "valid"\n    return {"id": doc.id, "doc_type": doc.doc_type, "doc_number": doc.doc_number,\n            "expiry_date": doc.expiry_date.isoformat() if doc.expiry_date else None,\n            "days_left": days_left, "status": status, "file_ref": doc.file_ref}\n\n\ndef list_documents(db: Session, contractor: Contractor) -> list[dict]:\n    docs = db.scalars(select(VaultDocument).where(VaultDocument.contractor_id == contractor.id)\n                      .order_by(VaultDocument.expiry_date.is_(None), VaultDocument.expiry_date))\n    return [serialize(d) for d in docs]\n\n\ndef expiring_documents(db: Session, contractor: Contractor, within_days: int | None = None) -> list[dict]:\n    within = within_days if within_days is not None else get_settings().expiry_alert_days\n    return [d for d in list_documents(db, contractor) if d["days_left"] is not None and d["days_left"] <= within]\n\n\ndef alert_text(contractor: Contractor, items: list[dict]) -> str:\n    lines = [f"🔔 *TenderBot AI — कागदपत्र नूतनीकरण अलर्ट*", f"नमस्कार {contractor.name or \'भाऊ\'},"]\n    for it in items:\n        when = f"{it[\'days_left\']} दिवसांत संपत आहे" if it["days_left"] >= 0 else f"{abs(it[\'days_left\'])} दिवसांपूर्वी संपले आहे"\n        number = f" ({it[\'doc_number\']})" if it["doc_number"] else ""\n        lines.append(f"• {it[\'doc_type\']}{number} — {fmt_date(date.fromisoformat(it[\'expiry_date\']))} रोजी {when}")\n    lines.append("टेंडर भरण्यापूर्वी नूतनीकरण पूर्ण करा.")\n    return "\\n".join(lines)\n\n\ndef run_expiry_alerts(db: Session, today: date | None = None) -> dict:\n    """Send WhatsApp alerts for documents expiring within the alert window. Safe to run daily."""\n    today = today or date.today()\n    window = get_settings().expiry_alert_days\n    sent = skipped_locked = 0\n    for contractor in db.scalars(select(Contractor)):\n        allowed, _ = check_access(contractor, "alerts")\n        due: list[VaultDocument] = []\n        for doc in contractor.documents:\n            if doc.expiry_date is None:\n                continue\n            days_left = (doc.expiry_date - today).days\n            if days_left > window:\n                continue\n            recently = doc.last_alert_on is not None and (today - doc.last_alert_on).days < (1 if days_left <= 3 else 7)\n            if not recently:\n                due.append(doc)\n        if not due:\n            continue\n        if not allowed:\n            skipped_locked += 1\n            continue\n        items = [serialize(d, today) for d in due]\n        result = send_whatsapp(contractor.phone, alert_text(contractor, items))\n        logger.info("vault alert to %s: %s", contractor.phone, result.get("mode"))\n        for doc in due:\n            doc.last_alert_on = today\n        db.commit()\n        sent += 1\n    return {"contractors_alerted": sent, "skipped_plan_locked": skipped_locked}\n',
    'agents/payment_delay_agent.py': '"""Payment delay tracking across department desks + formal Marathi follow-up letter generator."""\nfrom __future__ import annotations\n\nfrom datetime import date, timedelta\n\nfrom agents import fmt_date, format_inr\nfrom database import PaymentBill\n\n\ndef delay_days(bill_submitted_on: date, today: date | None = None) -> int:\n    return max(((today or date.today()) - bill_submitted_on).days, 0)\n\n\ndef escalation_level(days: int) -> tuple[int, str]:\n    if days < 30:\n        return 1, "पहिले स्मरणपत्र"\n    if days < 60:\n        return 2, "दुसरे स्मरणपत्र"\n    return 3, "अंतिम स्मरणपत्र / नोटीस"\n\n\ndef desk_summary(desk_trail: list[dict], today: date | None = None) -> tuple[str | None, list[str]]:\n    """Return (current desk, human readable lines) from the recorded desk trail."""\n    today = today or date.today()\n    lines: list[str] = []\n    entries = sorted(desk_trail, key=lambda e: e.get("received_on") or "")\n    for i, entry in enumerate(entries):\n        start = date.fromisoformat(entry["received_on"]) if entry.get("received_on") else None\n        end = date.fromisoformat(entries[i + 1]["received_on"]) if i + 1 < len(entries) and entries[i + 1].get("received_on") else today\n        held = f" — {max((end - start).days, 0)} दिवस" if start else ""\n        remark = f" ({entry[\'remarks\']})" if entry.get("remarks") else ""\n        lines.append(f"{i + 1}. {entry[\'desk\']}: {fmt_date(start)} पासून{held}{remark}")\n    return (entries[-1]["desk"] if entries else None), lines\n\n\ndef generate_notice(bill: PaymentBill, contractor_name: str, officer_designation: str,\n                    office_address: str | None, today: date | None = None) -> dict:\n    today = today or date.today()\n    days = delay_days(bill.bill_submitted_on, today)\n    level, label = escalation_level(days)\n    current_desk, trail_lines = desk_summary(bill.desk_trail or [], today)\n\n    parts = [\n        "प्रति,",\n        f"{officer_designation},",\n        f"{bill.department}" + (f",\\n{office_address}" if office_address else ""),\n        "",\n        f"दिनांक: {fmt_date(today)}",\n        "",\n        f"विषय: {bill.work_name} — देयक क्र. {bill.bill_no} (रक्कम {format_inr(bill.bill_amount)}) चे प्रलंबित देयक अदा करणेबाबत — {label}",\n    ]\n    if bill.work_order_no:\n        parts.append(f"संदर्भ: कार्यारंभ आदेश क्र. {bill.work_order_no}")\n    parts += [\n        "",\n        "महोदय,",\n        "",\n        f"उपरोक्त विषयाच्या संदर्भात आमच्या {contractor_name} या फर्मने \'{bill.work_name}\' या कामाचे देयक क्र. {bill.bill_no}, "\n        f"रक्कम {format_inr(bill.bill_amount)}, दिनांक {fmt_date(bill.bill_submitted_on)} रोजी आपल्या कार्यालयात सादर केले आहे. "\n        f"आजपर्यंत {days} दिवस उलटूनही सदर देयकाची रक्कम अदा करण्यात आलेली नाही.",\n    ]\n    if trail_lines:\n        parts += ["", "देयकाचा आतापर्यंतचा प्रवास (टेबलनिहाय):"] + trail_lines\n        if current_desk:\n            parts.append(f"सध्या देयक \'{current_desk}\' येथे प्रलंबित असल्याचे आमच्या नोंदीनुसार दिसते.")\n    closing = {\n        1: "तरी सदर देयकाची कार्यवाही तातडीने पूर्ण करून रक्कम लवकरात लवकर अदा करावी, ही नम्र विनंती.",\n        2: "यापूर्वीही आम्ही विनंती केली असून अद्याप कार्यवाही न झाल्याने आर्थिक अडचण निर्माण झाली आहे. "\n           "तरी सदर देयक तातडीने मंजूर करून रक्कम अदा करावी, ही विनंती.",\n        3: "वारंवार विनंती करूनही देयक अदा न झाल्याने आमच्या कामकाजावर गंभीर परिणाम होत आहे. "\n           "सदर देयक ७ दिवसांत अदा न झाल्यास, कराराच्या अटींनुसार आणि उपलब्ध कायदेशीर मार्गांनी पुढील कार्यवाही करण्यास आम्हाला भाग पडेल, याची कृपया नोंद घ्यावी.",\n    }[level]\n    parts += ["", closing, "", "धन्यवाद.", "", "आपला विश्वासू,", contractor_name, "(अधिकृत स्वाक्षरी व शिक्का)",\n              "", "सोबत: देयकाची प्रत व पोचपावती"]\n    return {\n        "delay_days": days,\n        "escalation_level": level,\n        "escalation_label": label,\n        "current_desk": current_desk,\n        "desk_trail_summary": trail_lines,\n        "notice_mr": "\\n".join(parts),\n        "suggested_next_followup_on": (today + timedelta(days=7 if level == 3 else 15)).isoformat(),\n    }\n',
    'agents/communication_agent.py': '"""Twilio WhatsApp + Marathi/English voice calls, YES/NO parsing, submission dispatch."""\nfrom __future__ import annotations\n\nimport json\nimport re\n\nimport httpx\nfrom twilio.rest import Client\nfrom twilio.twiml.messaging_response import MessagingResponse\nfrom twilio.twiml.voice_response import Gather, VoiceResponse\n\nfrom agents import format_inr, logger\nfrom config import get_settings\nfrom database import Submission, normalize_phone\n\nMARATHI_VOICE = "Google.mr-IN-Standard-A"\nENGLISH_VOICE = "Google.en-IN-Standard-A"\n\nYES_WORDS = {"yes", "y", "ok", "okay", "हो", "होय", "हां", "हा", "ठीक", "1"}\nNO_WORDS = {"no", "n", "cancel", "नाही", "नको", "नाहि", "रद्द", "2"}\n\n\ndef _client() -> Client:\n    s = get_settings()\n    return Client(s.twilio_account_sid, s.twilio_auth_token)\n\n\ndef parse_decision(body: str | None) -> str | None:\n    """Map a reply to \'YES\' / \'NO\' / None."""\n    text = re.sub(r"[^\\w\\s]", "", (body or "").strip().lower())\n    if text in YES_WORDS:\n        return "YES"\n    if text in NO_WORDS:\n        return "NO"\n    return None\n\n\ndef send_whatsapp(to: str, body: str, content_variables: dict | None = None) -> dict:\n    """Send a WhatsApp message. Without Twilio credentials it returns a dry-run result (nothing is sent)."""\n    s = get_settings()\n    to_addr = "whatsapp:" + normalize_phone(to)\n    if not s.twilio_configured:\n        logger.warning("Twilio not configured — WhatsApp dry run to %s", to_addr)\n        return {"sent": False, "mode": "dry_run", "to": to_addr, "body": body}\n    try:\n        kwargs: dict = {"from_": s.twilio_whatsapp_from, "to": to_addr}\n        if content_variables is not None and s.twilio_approval_content_sid:\n            kwargs.update(content_sid=s.twilio_approval_content_sid, content_variables=json.dumps(content_variables))\n        else:\n            kwargs["body"] = body\n        message = _client().messages.create(**kwargs)\n        return {"sent": True, "mode": "twilio", "to": to_addr, "sid": message.sid}\n    except Exception as exc:\n        logger.error("WhatsApp send failed: %s", exc)\n        return {"sent": False, "mode": "error", "to": to_addr, "error": str(exc)}\n\n\ndef send_approval_prompt(to: str, tender_title: str, bid_amount: float) -> dict:\n    text = (\n        f"भाऊ, {format_inr(bid_amount)} चे टेंडर सबमिट करू का?\\n"\n        f"टेंडर: {tender_title}\\n\\nउत्तर द्या: *YES* (सबमिट करा) किंवा *NO* (रद्द करा)"\n    )\n    return send_whatsapp(to, text, content_variables={"1": tender_title, "2": format_inr(bid_amount)})\n\n\ndef make_voice_call(to: str, submission_id: int) -> dict:\n    s = get_settings()\n    to_number = normalize_phone(to)\n    if not (s.twilio_configured and s.twilio_voice_from):\n        logger.warning("Twilio voice not configured — dry run call to %s", to_number)\n        return {"called": False, "mode": "dry_run", "to": to_number}\n    try:\n        call = _client().calls.create(\n            to=to_number, from_=s.twilio_voice_from,\n            url=f"{s.public_base_url.rstrip(\'/\')}/voice-prompt/{submission_id}", method="POST",\n        )\n        return {"called": True, "mode": "twilio", "to": to_number, "sid": call.sid}\n    except Exception as exc:\n        logger.error("Voice call failed: %s", exc)\n        return {"called": False, "mode": "error", "to": to_number, "error": str(exc)}\n\n\ndef voice_prompt_twiml(submission: Submission) -> str:\n    base = get_settings().public_base_url.rstrip("/")\n    amount = f"{int(round(submission.bid_amount))}"\n    response = VoiceResponse()\n    gather = Gather(num_digits=1, action=f"{base}/voice-response/{submission.id}", method="POST", timeout=10)\n    gather.say(\n        f"नमस्कार भाऊ. टेंडर बॅाट बोलतोय. {submission.tender_title} या टेंडरसाठी रुपये {amount} ची बिड सबमिट करू का? "\n        "सबमिट करण्यासाठी एक दाबा. रद्द करण्यासाठी दोन दाबा.",\n        voice=MARATHI_VOICE, language="mr-IN",\n    )\n    gather.say(\n        f"This is TenderBot. Shall I submit the bid of rupees {amount}? Press 1 to submit, press 2 to cancel.",\n        voice=ENGLISH_VOICE, language="en-IN",\n    )\n    response.append(gather)\n    response.say("उत्तर मिळाले नाही. आम्ही तुम्हाला व्हॉट्सॲपवर विचारू. धन्यवाद.", voice=MARATHI_VOICE, language="mr-IN")\n    return str(response)\n\n\ndef voice_result_twiml(decision: str | None, extra: str = "") -> str:\n    response = VoiceResponse()\n    if decision == "YES":\n        text = "ठीक आहे भाऊ, सबमिशनसाठी मंजुरी नोंदवली आहे. " + extra\n    elif decision == "NO":\n        text = "ठीक आहे भाऊ, टेंडर रद्द केले आहे."\n    elif decision == "BLOCKED":\n        text = "भाऊ, तुमचा प्लॅन सक्रिय नसल्याने सबमिशन होऊ शकत नाही. तपशील व्हॉट्सॲपवर पाठवला आहे."\n    else:\n        text = "क्षमस्व, तुमचे उत्तर समजले नाही. कृपया व्हॉट्सॲपवर YES किंवा NO पाठवा."\n    response.say(text, voice=MARATHI_VOICE, language="mr-IN")\n    return str(response)\n\n\ndef whatsapp_reply_twiml(message: str) -> str:\n    reply = MessagingResponse()\n    reply.message(message)\n    return str(reply)\n\n\ndef dispatch_submission(submission: Submission) -> tuple[str, str]:\n    """Execute an approved submission. Returns (status, detail).\n\n    Portal submission needs your Digital Signature Certificate, so it is performed by the service behind\n    SUBMISSION_WEBHOOK_URL. Without it the bid is marked approved and waits for portal submission — it is\n    NEVER reported as SUBMITTED unless the downstream service confirms with a 2xx response.\n    """\n    url = get_settings().submission_webhook_url\n    if not url:\n        return ("APPROVED_AWAITING_PORTAL_SUBMISSION",\n                "मंजुरी नोंदवली. पोर्टलवर DSC ने प्रत्यक्ष सबमिशन अजून बाकी आहे.")\n    payload = {"submission_id": submission.id, "tender_ref": submission.tender_ref,\n               "tender_title": submission.tender_title, "bid_amount": submission.bid_amount}\n    try:\n        response = httpx.post(url, json=payload, timeout=60)\n        response.raise_for_status()\n        return "SUBMITTED", "सबमिशन सेवेने यशस्वी असल्याचे कळवले."\n    except Exception as exc:\n        logger.error("submission webhook failed: %s", exc)\n        return "APPROVED_SUBMISSION_FAILED", f"सबमिशन सेवा अयशस्वी: {exc}"\n',
    'agents/tax_agent.py': '"""GST liability, Input Tax Credit and CA-ready breakdown. All numbers are computed from supplied inputs."""\nfrom __future__ import annotations\n\nfrom agents import format_inr, llm_available, llm_text, logger\nfrom config import get_settings\nfrom system_prompt import MASTER_SYSTEM_PROMPT\n\nDISCLAIMER_MR = (\n    "हे आकडे तुम्ही दिलेल्या माहितीवर आधारित अंदाज आहेत. अंतिम रिटर्न भरण्यापूर्वी तुमच्या सीए कडून खात्री करा. "\n    "कामाच्या प्रकारानुसार GST दर वेगळा असू शकतो."\n)\n\nGENERAL_STRATEGIES_MR = [\n    "ITC फक्त वैध टॅक्स इन्व्हॉइस आणि GSTR-2B मध्ये दिसणाऱ्या खरेदीवरच क्लेम करा; पुरवठादाराने रिटर्न भरले आहे का ते तपासा.",\n    "प्रत्येक खरेदी बिलावर तुमचा GSTIN आणि योग्य HSN/SAC आहे याची खात्री करा, म्हणजे ITC नाकारला जाणार नाही.",\n    "GSTR-1 आणि GSTR-3B वेळेत भरा; उशिरा भरल्यास दंड आणि व्याज लागू शकते.",\n    "सरकारी विभागाकडून GST TDS कापला गेल्यास तो तुमच्या इलेक्ट्रॉनिक कॅश लेजरमध्ये जमा होतो; तो पुढील देयकात वापरा.",\n]\n\n\ndef compute(taxable_value: float, gst_rate_percent: float, intra_state: bool,\n            purchases: list[dict], gst_tds_applicable: bool) -> dict:\n    s = get_settings()\n    r2 = lambda v: round(v + 1e-9, 2)\n\n    output_total = r2(taxable_value * gst_rate_percent / 100)\n    if intra_state:\n        half = r2(output_total / 2)\n        output = {"cgst": half, "sgst": r2(output_total - half), "igst": 0.0, "total": output_total}\n    else:\n        output = {"cgst": 0.0, "sgst": 0.0, "igst": output_total, "total": output_total}\n    invoice_total = r2(taxable_value + output_total)\n\n    items, eligible_total, blocked_total = [], 0.0, 0.0\n    for p in purchases:\n        tax = r2(p["taxable_value"] * p["gst_rate_percent"] / 100)\n        items.append({**p, "gst_amount": tax})\n        if p["itc_eligible"]:\n            eligible_total += tax\n        else:\n            blocked_total += tax\n    eligible_total, blocked_total = r2(eligible_total), r2(blocked_total)\n\n    net = r2(output_total - eligible_total)\n    payable = max(net, 0.0)\n    carry_forward = r2(-net) if net < 0 else 0.0\n\n    tds = None\n    receipt = invoice_total\n    if gst_tds_applicable:\n        applies = taxable_value > s.gst_tds_threshold\n        amount = r2(taxable_value * s.gst_tds_rate_percent / 100) if applies else 0.0\n        tds = {\n            "applies": applies, "rate_percent": s.gst_tds_rate_percent, "amount": amount,\n            "note_mr": ("GST TDS लागू (मर्यादेपेक्षा जास्त मूल्य); रक्कम तुमच्या कॅश लेजरमध्ये जमा होईल."\n                        if applies else f"मूल्य {format_inr(s.gst_tds_threshold)} किंवा कमी असल्याने TDS लागू नाही."),\n        }\n        receipt = r2(invoice_total - amount)\n        tds["cash_payable_after_tds_credit"] = max(r2(payable - amount), 0.0)\n\n    breakdown = [\n        {"particular": "करपात्र मूल्य (Taxable Value)", "amount": r2(taxable_value)},\n        {"particular": f"आउटपुट GST @ {gst_rate_percent:g}%", "amount": output_total},\n    ]\n    if intra_state:\n        breakdown += [{"particular": "  CGST", "amount": output["cgst"]}, {"particular": "  SGST", "amount": output["sgst"]}]\n    else:\n        breakdown.append({"particular": "  IGST", "amount": output["igst"]})\n    breakdown += [\n        {"particular": "एकूण इन्व्हॉइस मूल्य", "amount": invoice_total},\n        {"particular": "पात्र ITC (वजा)", "amount": eligible_total},\n        {"particular": "ब्लॉक/अपात्र ITC (क्लेम नाही)", "amount": blocked_total},\n        {"particular": "निव्वळ GST देय", "amount": payable},\n    ]\n    if carry_forward:\n        breakdown.append({"particular": "पुढे नेता येणारा ITC (क्रेडिट शिल्लक)", "amount": carry_forward})\n    if tds:\n        breakdown += [{"particular": "GST TDS (विभागाकडून कपात)", "amount": tds["amount"]},\n                      {"particular": "प्रत्यक्ष मिळणारी रक्कम", "amount": receipt}]\n\n    result = {\n        "inputs": {"taxable_value": r2(taxable_value), "gst_rate_percent": gst_rate_percent,\n                   "supply_type": "intra_state (CGST+SGST)" if intra_state else "inter_state (IGST)"},\n        "output_tax": output, "invoice_total": invoice_total,\n        "itc": {"eligible_total": eligible_total, "blocked_total": blocked_total, "items": items},\n        "net_gst_payable": payable, "itc_carry_forward": carry_forward,\n        "gst_tds": tds, "expected_receipt": receipt,\n        "ca_ready_breakdown": breakdown,\n        "disclaimer_mr": DISCLAIMER_MR,\n    }\n    result["summary_mr"] = (\n        f"आउटपुट GST {format_inr(output_total)}, पात्र ITC {format_inr(eligible_total)}, "\n        f"निव्वळ GST देय {format_inr(payable)}."\n        + (f" ITC शिल्लक {format_inr(carry_forward)} पुढे नेता येईल." if carry_forward else "")\n    )\n    result["strategies_mr"] = _strategies(result)\n    return result\n\n\ndef _strategies(result: dict) -> list[str]:\n    strategies = list(GENERAL_STRATEGIES_MR)\n    if result["itc"]["blocked_total"] > 0:\n        strategies.insert(0, "काही खरेदीवरील ITC अपात्र धरला आहे; त्या खरेदीची पात्रता सीए कडून पुन्हा तपासा.")\n    if not llm_available():\n        return strategies\n    try:\n        system = (MASTER_SYSTEM_PROMPT +\n                  "\\nखालील गणिताच्या आधारे ३ छोट्या मराठी टॅक्स-नियोजन सूचना दे. फक्त दिलेले आकडे वापर; नवीन आकडे किंवा कायदेशीर कलमे बनवू नकोस. "\n                  "प्रत्येक सूचना वेगळ्या ओळीत, बुलेटशिवाय.")\n        text = llm_text(system, result["summary_mr"] + "\\n" + "\\n".join(f"{b[\'particular\']}: {b[\'amount\']}" for b in result["ca_ready_breakdown"]))\n        ai_lines = [ln.strip(" -•\\t") for ln in text.splitlines() if ln.strip()]\n        return ai_lines[:3] + strategies\n    except Exception as exc:\n        logger.warning("tax strategy LLM failed: %s", exc)\n        return strategies\n',
    'main.py': '"""TenderBot AI — FastAPI application."""\nfrom __future__ import annotations\n\nimport asyncio\nimport hashlib\nimport logging\nfrom contextlib import asynccontextmanager\nfrom datetime import date\n\nfrom fastapi import Depends, FastAPI, Header, HTTPException, Query, Request, Response\nfrom pydantic import BaseModel, Field\nfrom sqlalchemy import or_, select, text\nfrom sqlalchemy.orm import Session\n\nfrom agents import LLMUnavailable, format_inr, llm_available\nfrom agents import (analyzer_agent, bg_emd_agent, communication_agent, competitor_agent, marketplace_agent,\n                    payment_delay_agent, scraper_agent, tax_agent, vault_agent)\nfrom config import get_settings\nfrom pwa import router as pwa_router\nfrom database import (Contractor, PaymentBill, SessionLocal, Submission, Tender, check_access, get_db,\n                      get_or_create_contractor, init_db, normalize_phone, utcnow)\n\nlogging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(name)s: %(message)s")\nlogger = logging.getLogger("tenderbot")\nsettings = get_settings()\n\n\n# ------------------------------------------------------------------ scheduler\nasync def _vault_loop() -> None:\n    while True:\n        try:\n            def job():\n                with SessionLocal() as db:\n                    return vault_agent.run_expiry_alerts(db)\n            logger.info("vault expiry run: %s", await asyncio.to_thread(job))\n        except Exception:\n            logger.exception("vault expiry run failed")\n        await asyncio.sleep(settings.vault_check_interval_hours * 3600)\n\n\n@asynccontextmanager\nasync def lifespan(_: FastAPI):\n    init_db()\n    task = asyncio.create_task(_vault_loop()) if settings.enable_scheduler else None\n    yield\n    if task:\n        task.cancel()\n\n\napp = FastAPI(title=settings.app_name, version=settings.app_version, lifespan=lifespan)\napp.include_router(pwa_router)\n\n\n# ------------------------------------------------------------------ schemas (Pydantic v2)\nclass VendorProfile(BaseModel):\n    phone: str = Field(description="WhatsApp number, e.g. +919876543210")\n    name: str\n    contractor_class: str | None = None\n    categories: list[str] = Field(default_factory=list)\n    districts: list[str] = Field(default_factory=list)\n    annual_turnover: float | None = Field(default=None, ge=0)\n    documents_held: list[str] = Field(default_factory=list)\n\n\nclass TenderInfo(BaseModel):\n    tender_id: str\n    title: str\n    department: str\n    category: str\n    district: str | None = None\n    estimated_cost: float = Field(gt=0)\n    emd_amount: float | None = Field(default=None, ge=0)\n    required_documents: list[str] = Field(default_factory=list)\n    minimum_class: str | None = None\n    min_turnover: float | None = Field(default=None, ge=0)\n    tender_text: str | None = Field(default=None, description="Raw tender text; requirements are extracted with GPT-4o if no required_documents given")\n    source_url: str | None = None\n\n\nclass AnalyzeRequest(BaseModel):\n    vendor: VendorProfile\n    tender: TenderInfo\n    send_whatsapp: bool = True\n\n\nclass BidRateRequest(BaseModel):\n    phone: str\n    tender: TenderInfo\n    own_cost_estimate: float | None = Field(default=None, gt=0, description="Your own estimated execution cost (INR)")\n\n\nclass SubmitApprovalRequest(BaseModel):\n    phone: str\n    tender_id: str\n    tender_title: str\n    bid_amount: float = Field(gt=0)\n    place_call: bool = True\n\n\nclass PaymentDesk(BaseModel):\n    desk: str\n    received_on: date | None = None\n    remarks: str | None = None\n\n\nclass PaymentNoticeRequest(BaseModel):\n    phone: str\n    contractor_name: str\n    department: str\n    office_address: str | None = None\n    officer_designation: str = "कार्यकारी अभियंता"\n    work_name: str\n    work_order_no: str | None = None\n    bill_no: str\n    bill_amount: float = Field(gt=0)\n    bill_submitted_on: date\n    desk_trail: list[PaymentDesk] = Field(default_factory=list)\n    send_whatsapp: bool = False\n\n\nclass PurchaseItem(BaseModel):\n    description: str\n    taxable_value: float = Field(ge=0)\n    gst_rate_percent: float = Field(ge=0, le=28)\n    itc_eligible: bool = True\n\n\nclass TaxRequest(BaseModel):\n    phone: str\n    taxable_value: float = Field(gt=0)\n    gst_rate_percent: float | None = Field(default=None, ge=0, le=28)\n    intra_state: bool = True\n    purchases: list[PurchaseItem] = Field(default_factory=list)\n    gst_tds_applicable: bool = False\n\n\nclass EmdKitRequest(BaseModel):\n    phone: str\n    contractor_name: str\n    tender_id: str\n    tender_title: str\n    department: str\n    bg_type: str = Field(default="EMD_BG", pattern="^(EMD_BG|PERFORMANCE_BG)$")\n    guarantee_amount: float = Field(gt=0)\n    validity_months: int = Field(default=6, ge=1, le=120)\n    bank_name: str | None = None\n    branch: str | None = None\n    account_number_last4: str | None = Field(default=None, pattern=r"^\\d{4}$")\n    beneficiary: str | None = None\n    send_whatsapp: bool = True\n\n\nclass VaultDocIn(BaseModel):\n    phone: str\n    doc_type: str\n    doc_number: str | None = None\n    expiry_date: date | None = None\n    file_ref: str | None = None\n\n\nclass AwardedIngestRequest(BaseModel):\n    source: str = Field(pattern="^(Mahatenders|CPPP)$")\n    url: str | None = None\n    category: str | None = None\n    department: str | None = None\n    records: list[dict] = Field(default_factory=list)\n\n\nclass VendorIn(BaseModel):\n    name: str\n    category: str\n    district: str\n    phone: str\n    rate: float | None = None\n    rate_unit: str | None = None\n    verified_by: str | None = None\n    last_verified_on: date | None = None\n\n\nclass SetPlanRequest(BaseModel):\n    phone: str\n    plan: str = Field(pattern="^(none|basic|vip)$")\n    days: int = Field(default=30, ge=1, le=366)\n\n\nclass DiscoverRequest(BaseModel):\n    url: str\n    category: str | None = None\n    district: str | None = None\n    save: bool = True\n\n\nclass TenderIn(BaseModel):\n    phone: str\n    tender_id: str = Field(min_length=1)\n    title: str = Field(min_length=1)\n    department: str = Field(min_length=1)\n    category: str = "general"\n    district: str | None = None\n    estimated_cost: float = Field(gt=0)\n    emd_amount: float | None = Field(default=None, ge=0)\n    source_url: str | None = None\n\n\nclass ProfileIn(BaseModel):\n    phone: str\n    name: str | None = None\n    contractor_class: str | None = None\n    categories: list[str] = Field(default_factory=list)\n    districts: list[str] = Field(default_factory=list)\n    annual_turnover: float | None = Field(default=None, ge=0)\n\n\nclass DecisionIn(BaseModel):\n    phone: str\n    decision: str = Field(pattern="^(YES|NO)$")\n\n\n# ------------------------------------------------------------------ helpers\ndef require_admin(x_admin_key: str | None = Header(default=None)) -> None:\n    if not settings.admin_api_key:\n        raise HTTPException(503, "ADMIN_API_KEY सेट केलेली नाही; admin एंडपॉइंट्स बंद आहेत.")\n    if x_admin_key != settings.admin_api_key:\n        raise HTTPException(401, "अवैध admin key")\n\n\ndef contractor_for(db: Session, phone: str, **profile) -> Contractor:\n    try:\n        return get_or_create_contractor(db, phone, **profile)\n    except ValueError as exc:\n        raise HTTPException(422, str(exc))\n\n\ndef gate(contractor: Contractor, feature: str) -> None:\n    allowed, message = check_access(contractor, feature)\n    if not allowed:\n        raise HTTPException(402, detail={"message_mr": message, "plan_status": contractor.effective_plan(),\n                                         "trial_day": contractor.trial_day()})\n\n\ndef plan_info(contractor: Contractor) -> dict:\n    return {"plan_status": contractor.effective_plan(), "trial_day": contractor.trial_day(),\n            "trial_days_total": settings.trial_days}\n\n\ndef apply_decision(db: Session, submission: Submission, decision: str, channel: str) -> dict:\n    """Execute (YES) or cancel (NO) a pending submission. Idempotent for already-decided submissions."""\n    if submission.status != "PENDING":\n        return {"status": submission.status, "message_mr": "या सबमिशनवर आधीच निर्णय झाला आहे.", "already_decided": True}\n    submission.decision_channel = channel\n    submission.decided_at = utcnow()\n    if decision == "NO":\n        submission.status, submission.status_detail = "CANCELLED", "कंत्राटदाराने रद्द केले."\n        message = "ठीक आहे भाऊ, टेंडर सबमिशन रद्द केले आहे."\n    else:\n        contractor = db.get(Contractor, submission.contractor_id)\n        allowed, block_msg = check_access(contractor, "submit")\n        if not allowed:\n            submission.status, submission.status_detail = "CANCELLED", "प्लॅन/ट्रायलमुळे ब्लॉक."\n            db.commit()\n            return {"status": "CANCELLED", "message_mr": block_msg, "already_decided": False}\n        submission.status, submission.status_detail = communication_agent.dispatch_submission(submission)\n        message = {\n            "SUBMITTED": f"✅ भाऊ, {format_inr(submission.bid_amount)} चे टेंडर सबमिट झाले आहे.",\n            "APPROVED_AWAITING_PORTAL_SUBMISSION": (\n                f"👍 मंजुरी नोंदवली ({format_inr(submission.bid_amount)}). पोर्टलवर DSC ने सबमिशन अजून बाकी आहे — अजून सबमिट झालेले नाही."),\n            "APPROVED_SUBMISSION_FAILED": "⚠️ मंजुरी नोंदवली, पण सबमिशन सेवा अयशस्वी झाली. टेंडर अजून सबमिट झालेले नाही.",\n        }[submission.status]\n    db.commit()\n    return {"status": submission.status, "message_mr": message, "detail": submission.status_detail, "already_decided": False}\n\n\ndef xml(content: str) -> Response:\n    return Response(content=content, media_type="application/xml")\n\n\n# ------------------------------------------------------------------ 1. health\n@app.get("/")\ndef health(db: Session = Depends(get_db)) -> dict:\n    db.execute(text("SELECT 1"))\n    return {\n        "app": settings.app_name, "version": settings.app_version, "status": "ok",\n        "database": "connected", "gpt4o_configured": llm_available(),\n        "twilio_configured": settings.twilio_configured,\n        "tagline_mr": "कंत्राटदाराचा हक्काचा आणि विश्वासू डिजिटल मॅनेजर",\n    }\n\n\n# ------------------------------------------------------------------ 2. analyze tender\n@app.post("/analyze-tender")\ndef analyze_tender(req: AnalyzeRequest, db: Session = Depends(get_db)) -> dict:\n    v, t = req.vendor, req.tender\n    contractor = contractor_for(db, v.phone, name=v.name, contractor_class=v.contractor_class,\n                                categories=v.categories, districts=v.districts, annual_turnover=v.annual_turnover)\n    gate(contractor, "analyze")\n\n    required_docs, minimum_class, min_turnover, emd = t.required_documents, t.minimum_class, t.min_turnover, t.emd_amount\n    source = "provided"\n    if not required_docs:\n        if not t.tender_text:\n            raise HTTPException(422, "required_documents किंवा tender_text द्या.")\n        try:\n            extracted = analyzer_agent.extract_requirements(t.tender_text)\n        except LLMUnavailable as exc:\n            raise HTTPException(503, f"tender_text वरून अटी काढण्यासाठी GPT-4o आवश्यक: {exc}")\n        required_docs = extracted["required_documents"]\n        minimum_class = minimum_class or extracted["minimum_class"]\n        min_turnover = min_turnover or extracted["min_turnover"]\n        emd = emd or extracted["emd_amount"]\n        source = "gpt4o_extracted"\n\n    existing = db.scalar(select(Tender).where(Tender.tender_ref == t.tender_id))\n    if existing is None:\n        db.add(Tender(tender_ref=t.tender_id, title=t.title, department=t.department, category=t.category,\n                      district=t.district, estimated_cost=t.estimated_cost, emd_amount=emd, source_url=t.source_url))\n        db.commit()\n\n    analysis = analyzer_agent.gap_analysis(required_docs, v.documents_held, v.contractor_class, minimum_class,\n                                           v.annual_turnover, min_turnover)\n    tender_view = {"tender_id": t.tender_id, "title": t.title, "department": t.department,\n                   "estimated_cost": t.estimated_cost, "emd_amount": emd}\n    alert_text = analyzer_agent.build_whatsapp_alert(tender_view, analysis)\n\n    alert_allowed, alert_block = check_access(contractor, "alerts")\n    if req.send_whatsapp and alert_allowed:\n        whatsapp = communication_agent.send_whatsapp(contractor.phone, alert_text)\n    else:\n        whatsapp = {"sent": False, "mode": "skipped",\n                    "reason_mr": alert_block if not alert_allowed else "send_whatsapp=false"}\n    return {"requirements_source": source, "required_documents": required_docs, "analysis": analysis,\n            "whatsapp_alert_text": alert_text, "whatsapp_delivery": whatsapp, **plan_info(contractor)}\n\n\n# ------------------------------------------------------------------ 3. predict bid rate\n@app.post("/predict-bid-rate")\ndef predict_bid_rate(req: BidRateRequest, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone)\n    gate(contractor, "predict_bid")\n    prediction = competitor_agent.predict_l1(db, req.tender.category, req.tender.department,\n                                             req.tender.estimated_cost, req.own_cost_estimate)\n    return {"tender_id": req.tender.tender_id, "estimated_cost": req.tender.estimated_cost,\n            "prediction": prediction, **plan_info(contractor)}\n\n\n# ------------------------------------------------------------------ 4. request submit approval\n@app.post("/request-submit-approval")\ndef request_submit_approval(req: SubmitApprovalRequest, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone)\n    gate(contractor, "submit")\n    submission = Submission(contractor_id=contractor.id, tender_ref=req.tender_id,\n                            tender_title=req.tender_title, bid_amount=req.bid_amount)\n    db.add(submission)\n    db.commit()\n    db.refresh(submission)\n\n    whatsapp = communication_agent.send_approval_prompt(contractor.phone, req.tender_title, req.bid_amount)\n    submission.whatsapp_sid = whatsapp.get("sid")\n\n    call: dict = {"called": False, "mode": "skipped"}\n    voice_allowed, voice_block = check_access(contractor, "voice")\n    if req.place_call:\n        if voice_allowed:\n            call = communication_agent.make_voice_call(contractor.phone, submission.id)\n            submission.call_sid = call.get("sid")\n        else:\n            call = {"called": False, "mode": "blocked", "reason_mr": voice_block}\n    db.commit()\n    return {"submission_id": submission.id, "status": submission.status,\n            "prompt_mr": f"भाऊ, {format_inr(req.bid_amount)} चे टेंडर सबमिट करू का?",\n            "whatsapp": whatsapp, "voice_call": call, **plan_info(contractor)}\n\n\n# ------------------------------------------------------------------ 5. WhatsApp webhook (YES/NO)\nasync def _verify_twilio(request: Request, form: dict) -> None:\n    if not settings.validate_twilio_signature:\n        return\n    from twilio.request_validator import RequestValidator\n    signature = request.headers.get("X-Twilio-Signature", "")\n    url = settings.public_base_url.rstrip("/") + request.url.path\n    if not RequestValidator(settings.twilio_auth_token).validate(url, form, signature):\n        raise HTTPException(403, "अवैध Twilio signature")\n\n\n@app.post("/whatsapp-webhook")\nasync def whatsapp_webhook(request: Request, db: Session = Depends(get_db)) -> Response:\n    form = {k: str(v) for k, v in (await request.form()).items()}\n    await _verify_twilio(request, form)\n    try:\n        phone = normalize_phone(form.get("From", ""))\n    except ValueError:\n        return xml(communication_agent.whatsapp_reply_twiml("नंबर ओळखता आला नाही."))\n\n    contractor = db.scalar(select(Contractor).where(Contractor.phone == phone))\n    pending = None\n    if contractor:\n        pending = db.scalar(select(Submission).where(Submission.contractor_id == contractor.id, Submission.status == "PENDING")\n                            .order_by(Submission.created_at.desc()))\n    if pending is None:\n        return xml(communication_agent.whatsapp_reply_twiml("भाऊ, सध्या मंजुरीसाठी कोणतेही टेंडर प्रलंबित नाही."))\n\n    decision = communication_agent.parse_decision(form.get("Body"))\n    if decision is None:\n        return xml(communication_agent.whatsapp_reply_twiml(\n            f"भाऊ, {format_inr(pending.bid_amount)} चे टेंडर सबमिट करू का? कृपया *YES* किंवा *NO* पाठवा."))\n    result = await asyncio.to_thread(apply_decision, db, pending, decision, "whatsapp")\n    return xml(communication_agent.whatsapp_reply_twiml(result["message_mr"]))\n\n\n# Voice-call endpoints used by Twilio (TwiML)\n@app.post("/voice-prompt/{submission_id}")\ndef voice_prompt(submission_id: int, db: Session = Depends(get_db)) -> Response:\n    submission = db.get(Submission, submission_id)\n    if submission is None or submission.status != "PENDING":\n        return xml(communication_agent.voice_result_twiml(None))\n    return xml(communication_agent.voice_prompt_twiml(submission))\n\n\n@app.post("/voice-response/{submission_id}")\nasync def voice_response(submission_id: int, request: Request, db: Session = Depends(get_db)) -> Response:\n    form = {k: str(v) for k, v in (await request.form()).items()}\n    await _verify_twilio(request, form)\n    submission = db.get(Submission, submission_id)\n    decision = {"1": "YES", "2": "NO"}.get(form.get("Digits", ""))\n    if submission is None or decision is None:\n        return xml(communication_agent.voice_result_twiml(None))\n    result = await asyncio.to_thread(apply_decision, db, submission, decision, "voice")\n    if decision == "YES" and result["status"] == "CANCELLED":\n        return xml(communication_agent.voice_result_twiml("BLOCKED"))\n    extra = "पोर्टलवरील सबमिशन अजून बाकी आहे." if submission.status == "APPROVED_AWAITING_PORTAL_SUBMISSION" else ""\n    return xml(communication_agent.voice_result_twiml(decision, extra))\n\n\n@app.get("/submissions/{submission_id}")\ndef submission_status(submission_id: int, db: Session = Depends(get_db)) -> dict:\n    s = db.get(Submission, submission_id)\n    if s is None:\n        raise HTTPException(404, "सबमिशन सापडले नाही")\n    return {"id": s.id, "tender_ref": s.tender_ref, "bid_amount": s.bid_amount, "status": s.status,\n            "detail": s.status_detail, "channel": s.decision_channel}\n\n\n# ------------------------------------------------------------------ 6. payment notice\n@app.post("/generate-payment-notice")\ndef generate_payment_notice(req: PaymentNoticeRequest, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone, name=req.contractor_name)\n    gate(contractor, "payment_notice")\n    trail = [{"desk": d.desk, "received_on": d.received_on.isoformat() if d.received_on else None, "remarks": d.remarks}\n             for d in req.desk_trail]\n    bill = db.scalar(select(PaymentBill).where(PaymentBill.contractor_id == contractor.id, PaymentBill.bill_no == req.bill_no,\n                                               PaymentBill.department == req.department))\n    if bill is None:\n        bill = PaymentBill(contractor_id=contractor.id, department=req.department, work_name=req.work_name,\n                           work_order_no=req.work_order_no, bill_no=req.bill_no, bill_amount=req.bill_amount,\n                           bill_submitted_on=req.bill_submitted_on, desk_trail=trail)\n        db.add(bill)\n    else:\n        bill.desk_trail = trail or bill.desk_trail\n        bill.bill_amount = req.bill_amount\n    notice = payment_delay_agent.generate_notice(bill, req.contractor_name, req.officer_designation, req.office_address)\n    bill.last_notice_on = date.today()\n    bill.notices_sent = (bill.notices_sent or 0) + 1\n    db.commit()\n    whatsapp = None\n    if req.send_whatsapp:\n        whatsapp = communication_agent.send_whatsapp(contractor.phone, notice["notice_mr"])\n    return {"bill_id": bill.id, **notice, "whatsapp_delivery": whatsapp, **plan_info(contractor)}\n\n\n# ------------------------------------------------------------------ 7. tax advice\n@app.post("/get-tax-advice")\ndef get_tax_advice(req: TaxRequest, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone)\n    gate(contractor, "tax_draft")\n    rate = req.gst_rate_percent if req.gst_rate_percent is not None else settings.gst_rate_percent\n    result = tax_agent.compute(req.taxable_value, rate, req.intra_state,\n                               [p.model_dump() for p in req.purchases], req.gst_tds_applicable)\n    export_allowed, export_block = check_access(contractor, "tax_export")\n    result["ca_ready_export"] = {"available": export_allowed}\n    if not export_allowed:\n        result["ca_ready_export"]["message_mr"] = export_block\n        result["ca_ready_breakdown"] = None\n        result["draft_only"] = True\n    return {**result, **plan_info(contractor)}\n\n\n# ------------------------------------------------------------------ extra feature endpoints\n@app.post("/generate-emd-kit")\ndef generate_emd_kit(req: EmdKitRequest, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone, name=req.contractor_name)\n    gate(contractor, "bg_emd")\n    kit = bg_emd_agent.build_kit(req.contractor_name, req.tender_id, req.tender_title, req.department, req.bg_type,\n                                 req.guarantee_amount, req.validity_months, req.bank_name, req.branch,\n                                 req.account_number_last4, req.beneficiary)\n    kit["whatsapp_delivery"] = communication_agent.send_whatsapp(contractor.phone, kit["whatsapp_message"]) if req.send_whatsapp else None\n    return {**kit, **plan_info(contractor)}\n\n\n@app.get("/marketplace/search")\ndef marketplace_search(phone: str, category: str, district: str | None = None, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, phone)\n    gate(contractor, "marketplace")\n    return marketplace_agent.search_vendors(db, category, district)\n\n\n@app.post("/vault/documents")\ndef vault_add(req: VaultDocIn, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone)\n    gate(contractor, "vault")\n    doc = vault_agent.add_document(db, contractor, req.doc_type, req.doc_number, req.expiry_date, req.file_ref)\n    return vault_agent.serialize(doc)\n\n\n@app.get("/vault/documents")\ndef vault_list(phone: str, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, phone)\n    gate(contractor, "vault")\n    return {"documents": vault_agent.list_documents(db, contractor),\n            "expiring_within_alert_window": vault_agent.expiring_documents(db, contractor)}\n\n\n@app.post("/discover-tenders")\ndef discover_tenders(req: DiscoverRequest, db: Session = Depends(get_db)) -> dict:\n    try:\n        rows = scraper_agent.discover_active_tenders(req.url)\n    except ValueError as exc:\n        raise HTTPException(422, str(exc))\n    except Exception as exc:\n        raise HTTPException(502, f"पेज वाचता आले नाही: {exc}")\n    saved = 0\n    if req.save:\n        for row in rows:\n            ref = (row.get("tender_ref") or "").strip()\n            if not ref:\n                ref = "WEB-" + hashlib.sha1(f"{row.get(\'title\')}|{row[\'estimated_cost\']}".encode("utf-8")).hexdigest()[:12]\n            if db.scalar(select(Tender.id).where(Tender.tender_ref == ref)):\n                continue\n            db.add(Tender(tender_ref=ref, title=row.get("title") or ref, department=row.get("department") or "—",\n                          category=req.category or "general", district=req.district,\n                          estimated_cost=row["estimated_cost"], source_url=req.url))\n            saved += 1\n        db.commit()\n    return {"count": len(rows), "saved": saved, "tenders": rows[:100]}\n\n\ndef _tender_view(t: Tender) -> dict:\n    return {"tender_id": t.tender_ref, "title": t.title, "department": t.department, "category": t.category,\n            "district": t.district, "estimated_cost": t.estimated_cost, "emd_amount": t.emd_amount,\n            "source_url": t.source_url}\n\n\n@app.get("/tenders/search")\ndef tenders_search(q: str | None = None, category: str | None = None, district: str | None = None,\n                   department: str | None = None, min_cost: float | None = None, max_cost: float | None = None,\n                   limit: int = Query(50, ge=1, le=200), db: Session = Depends(get_db)) -> dict:\n    stmt = select(Tender)\n    if q and q.strip():\n        like = f"%{q.strip()}%"\n        stmt = stmt.where(or_(Tender.title.ilike(like), Tender.department.ilike(like), Tender.tender_ref.ilike(like)))\n    if category and category.strip():\n        stmt = stmt.where(Tender.category.ilike(f"%{category.strip()}%"))\n    if district and district.strip():\n        stmt = stmt.where(Tender.district.ilike(f"%{district.strip()}%"))\n    if department and department.strip():\n        stmt = stmt.where(Tender.department.ilike(f"%{department.strip()}%"))\n    if min_cost is not None:\n        stmt = stmt.where(Tender.estimated_cost >= min_cost)\n    if max_cost is not None:\n        stmt = stmt.where(Tender.estimated_cost <= max_cost)\n    rows = list(db.scalars(stmt.order_by(Tender.created_at.desc()).limit(limit)))\n    return {"count": len(rows), "tenders": [_tender_view(t) for t in rows]}\n\n\n@app.post("/tenders")\ndef tenders_upsert(req: TenderIn, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone)\n    gate(contractor, "analyze")\n    tender = db.scalar(select(Tender).where(Tender.tender_ref == req.tender_id))\n    if tender is None:\n        tender = Tender(tender_ref=req.tender_id, title=req.title, department=req.department, category=req.category,\n                        district=req.district, estimated_cost=req.estimated_cost, emd_amount=req.emd_amount,\n                        source_url=req.source_url)\n        db.add(tender)\n    else:\n        tender.title, tender.department, tender.category = req.title, req.department, req.category\n        tender.district, tender.estimated_cost, tender.emd_amount = req.district, req.estimated_cost, req.emd_amount\n    db.commit()\n    return _tender_view(tender)\n\n\ndef _profile_view(c: Contractor) -> dict:\n    return {"phone": c.phone, "name": c.name, "contractor_class": c.contractor_class, "categories": c.categories or [],\n            "districts": c.districts or [], "annual_turnover": c.annual_turnover, **plan_info(c)}\n\n\n@app.get("/me")\ndef me_get(phone: str, db: Session = Depends(get_db)) -> dict:\n    return _profile_view(contractor_for(db, phone))\n\n\n@app.post("/me")\ndef me_save(req: ProfileIn, db: Session = Depends(get_db)) -> dict:\n    return _profile_view(contractor_for(db, req.phone, name=req.name, contractor_class=req.contractor_class,\n                                        categories=req.categories, districts=req.districts,\n                                        annual_turnover=req.annual_turnover))\n\n\n@app.get("/submissions")\ndef submissions_list(phone: str, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, phone)\n    rows = db.scalars(select(Submission).where(Submission.contractor_id == contractor.id)\n                      .order_by(Submission.created_at.desc()).limit(30))\n    return {"submissions": [{"id": s.id, "tender_ref": s.tender_ref, "tender_title": s.tender_title,\n                             "bid_amount": s.bid_amount, "status": s.status, "detail": s.status_detail,\n                             "created_at": s.created_at.isoformat()} for s in rows], **plan_info(contractor)}\n\n\n@app.post("/submissions/{submission_id}/decision")\ndef submission_decision(submission_id: int, req: DecisionIn, db: Session = Depends(get_db)) -> dict:\n    contractor = contractor_for(db, req.phone)\n    submission = db.get(Submission, submission_id)\n    if submission is None or submission.contractor_id != contractor.id:\n        raise HTTPException(404, "सबमिशन सापडले नाही")\n    return apply_decision(db, submission, req.decision, "app")\n\n\n# ------------------------------------------------------------------ admin\n@app.post("/admin/ingest-awarded-data", dependencies=[Depends(require_admin)])\ndef admin_ingest(req: AwardedIngestRequest, db: Session = Depends(get_db)) -> dict:\n    if not req.url and not req.records:\n        raise HTTPException(422, "url किंवा records द्या.")\n    try:\n        if req.url:\n            return scraper_agent.ingest_awarded_from_url(db, req.url, req.source, req.category, req.department)\n        return scraper_agent.ingest_awarded_json(db, req.records, req.source, req.category)\n    except ValueError as exc:\n        raise HTTPException(422, str(exc))\n    except Exception as exc:\n        raise HTTPException(502, f"इनजेस्ट अयशस्वी: {exc}")\n\n\n@app.post("/admin/vendors", dependencies=[Depends(require_admin)])\ndef admin_add_vendor(req: VendorIn, db: Session = Depends(get_db)) -> dict:\n    vendor = marketplace_agent.add_vendor(db, req.name, req.category, req.district, req.phone, req.rate,\n                                          req.rate_unit, req.verified_by, req.last_verified_on)\n    return {"id": vendor.id, "name": vendor.name}\n\n\n@app.post("/admin/set-plan", dependencies=[Depends(require_admin)])\ndef admin_set_plan(req: SetPlanRequest, db: Session = Depends(get_db)) -> dict:\n    from datetime import timedelta\n    contractor = contractor_for(db, req.phone)\n    contractor.plan = req.plan\n    contractor.plan_expires_at = utcnow() + timedelta(days=req.days) if req.plan != "none" else None\n    db.commit()\n    return {"phone": contractor.phone, **plan_info(contractor)}\n\n\n@app.post("/admin/run-vault-alerts", dependencies=[Depends(require_admin)])\ndef admin_run_vault_alerts(db: Session = Depends(get_db)) -> dict:\n    return vault_agent.run_expiry_alerts(db)\n\n\nif __name__ == "__main__":\n    import uvicorn\n    uvicorn.run("main:app", host="0.0.0.0", port=8000, reload=False)\n',
}


def main() -> None:
    root = Path(PROJECT_DIR)
    root.mkdir(exist_ok=True)
    for rel_path, content in FILES.items():
        target = root / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")
    # include this script itself in the project
    this_file = Path(__file__).resolve()
    if this_file.exists() and this_file != (root / "build_zip.py").resolve():
        shutil.copyfile(this_file, root / "build_zip.py")

    with zipfile.ZipFile(ZIP_NAME, "w", zipfile.ZIP_DEFLATED) as archive:
        for path in sorted(root.rglob("*")):
            if path.is_file() and "__pycache__" not in path.parts and path.suffix != ".pyc":
                archive.write(path, path.as_posix())
    print(f"Wrote {len(FILES) + 1} files to ./{PROJECT_DIR}/ and created {ZIP_NAME}")


if __name__ == "__main__":
    main()
